import{Z as r,B as s,h}from"./index-5a0e0c1f.js";const l=1,u=[{unitId:"s3u1",scene:"Meet a new classmate",sceneCn:"认识新同学",bigQuestion:"How do we greet a new friend?",bigQuestionCn:"怎样和新朋友打招呼？",tip:"先用 Hi 或 I’m ... 介绍自己，再用 Nice to meet you! 回应对方。",dialogue:[{speaker:"Mia",voice:"a",en:"Hi! I’m Mia. You’re Ben, right?",cn:"嗨！我是米娅。你是本，对吧？"},{speaker:"Ben",voice:"b",en:"Yes, I’m Ben. Nice to meet you!",cn:"是的，我是本。很高兴认识你！"},{speaker:"Mia",voice:"a",en:"Nice to meet you too. Show me your ruler, please.",cn:"我也很高兴认识你。请让我看看你的尺子。"},{speaker:"Ben",voice:"b",en:"Sure. Here you are.",cn:"当然。给你。"},{speaker:"Mia",voice:"a",en:"Thank you! Letters help us meet new friends.",cn:"谢谢你！字母帮助我们认识新朋友。"}]},{unitId:"s3u2",scene:"A guessing game",sceneCn:"猜一猜游戏",bigQuestion:"How do we ask about things?",bigQuestionCn:"怎样询问身边的事物？",tip:"What’s this? 用来问近处的东西，回答时用 It’s ...。",dialogue:[{speaker:"Ms Lin",voice:"a",en:"Look at the table, Ben. What’s this?",cn:"看这张桌子，本。这是什么？"},{speaker:"Ben",voice:"b",en:"It’s a hamburger. I know!",cn:"这是一个汉堡。我知道！"},{speaker:"Ms Lin",voice:"a",en:"Good! Can you guess this one?",cn:"很好！你能猜猜这个吗？"},{speaker:"Ben",voice:"b",en:"Is it chocolate?",cn:"这是巧克力吗？"},{speaker:"Ms Lin",voice:"a",en:"Yes! And this is a cookie. Chocolate and cookies are yummy.",cn:"对！这是一块饼干。巧克力和饼干都很好吃。"},{speaker:"Ben",voice:"b",en:"English and Chinese are fun!",cn:"英语和汉语真有趣！"}]},{unitId:"s3u3",scene:"Morning at the school gate",sceneCn:"校门口的早晨",bigQuestion:"How do we introduce ourselves and others?",bigQuestionCn:"怎样介绍自己和别人？",tip:"介绍别人用 This is ...，介绍自己用 My name is ... 或 I’m ...。",dialogue:[{speaker:"Mr Chen",voice:"b",en:"Good morning! What’s your name?",cn:"早上好！你叫什么名字？"},{speaker:"Amy",voice:"a",en:"Good morning, Mr Chen. My name is Amy.",cn:"早上好，陈老师。我叫艾米。"},{speaker:"Mr Chen",voice:"b",en:"This is Tom. He is a new student.",cn:"这是汤姆。他是一名新学生。"},{speaker:"Amy",voice:"a",en:"Nice to meet you, Tom.",cn:"很高兴认识你，汤姆。"},{speaker:"Tom",voice:"b",en:"Nice to meet you too. Here is my name card.",cn:"我也很高兴认识你。这是我的名字卡片。"},{speaker:"Mr Chen",voice:"b",en:"Welcome to Class Three, both of you!",cn:"欢迎你们俩来到三班！"}]},{unitId:"s3u4",scene:"Colour the keys",sceneCn:"给按键上色",bigQuestion:"How do we talk about colours and spelling?",bigQuestionCn:"怎样说颜色、问拼写？",tip:"问拼写说 How do you spell ...?，回答时把字母逐个读出来。",dialogue:[{speaker:"Ms Lin",voice:"a",en:"Look at the keyboard. What colour is it?",cn:"看这个键盘。它是什么颜色的？"},{speaker:"Leo",voice:"b",en:"It’s white.",cn:"它是白色的。"},{speaker:"Ms Lin",voice:"a",en:"Let’s colour the keys. Red, yellow, green and blue.",cn:"我们来给按键上色吧。红色、黄色、绿色和蓝色。"},{speaker:"Leo",voice:"b",en:"How do you spell “green”?",cn:"green 怎么拼写？"},{speaker:"Ms Lin",voice:"a",en:"G-R-E-E-N. Now you try.",cn:"G-R-E-E-N。你来试试。"},{speaker:"Leo",voice:"b",en:"G-R-E-E-N. I can spell it!",cn:"G-R-E-E-N。我会拼了！"}]},{unitId:"s3u5",scene:"Our class tablet",sceneCn:"班级平板",bigQuestion:"How do we set and say a password?",bigQuestionCn:"怎样设置并说出密码？",tip:"听不清时用 Can you say that again?，数字和字母要按顺序排好。",dialogue:[{speaker:"Mr Chen",voice:"b",en:"Let’s set a password for our class tablet.",cn:"我们来给班级平板设置密码吧。"},{speaker:"Mia",voice:"a",en:"Good idea. What’s the password?",cn:"好主意。密码是什么？"},{speaker:"Mr Chen",voice:"b",en:"Four letters and four numbers: M, I, A, S and three, five, seven, nine.",cn:"四个字母和四个数字：M、I、A、S，还有三、五、七、九。"},{speaker:"Mia",voice:"a",en:"Can you say that again? That’s a lot!",cn:"你能再说一遍吗？好多呀！"},{speaker:"Mr Chen",voice:"b",en:"Sure. Put them in order: M-I-A-S, three, five, seven, nine.",cn:"当然。把它们按顺序排好：M-I-A-S，三、五、七、九。"},{speaker:"Mia",voice:"a",en:"I see! Our password is safe now.",cn:"我明白了！现在我们的密码安全了。"}]},{unitId:"s3u6",scene:"Draw a face",sceneCn:"画一张脸",bigQuestion:"How do we talk about parts of the face?",bigQuestionCn:"怎样描述脸上的部位？",tip:"一个部位用 This is ...，多个部位用 These are ...。",dialogue:[{speaker:"Ms Lin",voice:"a",en:"Today we draw a face. Draw a big head first.",cn:"今天我们来画脸。先画一个大大的头。"},{speaker:"Lily",voice:"a",en:"This is the head. These are the eyes.",cn:"这是头。这些是眼睛。"},{speaker:"Ms Lin",voice:"a",en:"Good. What colour is the hair?",cn:"很好。头发是什么颜色的？"},{speaker:"Lily",voice:"a",en:"It’s black. Now I draw the nose and the mouth.",cn:"黑色的。现在我画鼻子和嘴巴。"},{speaker:"Ms Lin",voice:"a",en:"Where are the ears?",cn:"耳朵在哪里？"},{speaker:"Lily",voice:"a",en:"Here! This is a happy face.",cn:"在这里！这是一张快乐的脸。"}]},{unitId:"s3u7",scene:"Be a good listener",sceneCn:"做个好听众",bigQuestion:"What makes a good listener?",bigQuestionCn:"怎样才算好的倾听者？",tip:"听的时候看着对方、点点头；有疑问先说 I have a question。",dialogue:[{speaker:"Mr Chen",voice:"b",en:"Follow me, please. Look at this picture.",cn:"请跟我来。看这张图片。"},{speaker:"Tim",voice:"b",en:"I have a question.",cn:"我有一个问题。"},{speaker:"Mr Chen",voice:"b",en:"Yes, Tim?",cn:"怎么了，蒂姆？"},{speaker:"Tim",voice:"b",en:"I don’t understand this word.",cn:"我不明白这个单词。"},{speaker:"Mr Chen",voice:"b",en:"I see. Listen carefully, and keep quiet, please.",cn:"我明白了。请仔细听，保持安静。"},{speaker:"Mr Chen",voice:"b",en:"Good listeners nod and listen with their body and heart.",cn:"好的倾听者会点头，用身体和心去听。"},{speaker:"Tim",voice:"b",en:"Now I see! Thank you, Mr Chen.",cn:"现在我明白了！谢谢你，陈老师。"}]},{unitId:"s3u8",scene:"Animal moves",sceneCn:"动物模仿操",bigQuestion:"How do we invite others to move?",bigQuestionCn:"怎样邀请别人一起运动？",tip:"用 Let’s ... 发出邀请，用 Are you ready? 确认大家都准备好了。",dialogue:[{speaker:"Mr Zhou",voice:"b",en:"Let’s play an animal game. Are you ready?",cn:"我们来玩动物游戏。准备好了吗？"},{speaker:"Nina",voice:"a",en:"Yes! I can swim like a fish.",cn:"准备好了！我能像鱼一样游泳。"},{speaker:"Mr Zhou",voice:"b",en:"Good! Now jump like a monkey.",cn:"很好！现在像猴子一样跳。"},{speaker:"Kai",voice:"b",en:"Look! I can jump high.",cn:"看！我能跳得很高。"},{speaker:"Mr Zhou",voice:"b",en:"Move like a bird. Let’s fly!",cn:"像鸟一样移动。我们飞起来吧！"},{speaker:"Nina",voice:"a",en:"This is fun! I can move like a tiger, too!",cn:"真好玩！我还能像老虎一样动！"}]},{unitId:"x3u1",scene:"My morning routine",sceneCn:"我的早晨",bigQuestion:"How do we talk about our morning routine?",bigQuestionCn:"怎样讲述早晨的安排？",tip:"按顺序用 First、Then、After that 连接动作，别忘了 Don’t forget to ...。",dialogue:[{speaker:"Mum",voice:"a",en:"Get up, Ben. It’s seven o’clock.",cn:"起床了，本。七点了。"},{speaker:"Ben",voice:"b",en:"OK, Mum. I get dressed and brush my teeth.",cn:"好的，妈妈。我穿好衣服，刷好牙。"},{speaker:"Mum",voice:"a",en:"Then, wash your face and comb your hair.",cn:"然后洗脸、梳头。"},{speaker:"Ben",voice:"b",en:"After that, I have breakfast. I’m hungry!",cn:"之后我吃早饭。我饿了！"},{speaker:"Mum",voice:"a",en:"Don’t forget to pack your schoolbag.",cn:"别忘了收拾书包。"},{speaker:"Ben",voice:"b",en:"I won’t. Now I’m ready for school!",cn:"不会忘的。现在我准备好去上学了！"}]},{unitId:"x3u2",scene:"Late for class",sceneCn:"上课要迟到",bigQuestion:"How do we ask and tell the time?",bigQuestionCn:"怎样询问和表达时间？",tip:"整点用 It’s ten o’clock；半点可以用 half past ten 或 ten thirty。",dialogue:[{speaker:"Ben",voice:"b",en:"What time is it, Mia?",cn:"几点了，米娅？"},{speaker:"Mia",voice:"a",en:"It’s half past ten.",cn:"十点半。"},{speaker:"Ben",voice:"b",en:"Ten thirty! Oh no, it’s time to have class. I’m late!",cn:"十点半！糟糕，该上课了。我迟到了！"},{speaker:"Mia",voice:"a",en:"Hurry up! Let’s go to school.",cn:"快点！我们去学校吧。"},{speaker:"Ben",voice:"b",en:"We go home at four o’clock, right?",cn:"我们四点回家，对吗？"},{speaker:"Mia",voice:"a",en:"Yes. But now run!",cn:"对。但现在快跑！"}]},{unitId:"x3u3",scene:"After-school plan",sceneCn:"放学后的安排",bigQuestion:"How do we plan our day?",bigQuestionCn:"怎样规划一天的时间？",tip:"用 at 说时间点，用 from ... to ... 说时间段。",dialogue:[{speaker:"Lily",voice:"a",en:"What time do you have lunch, Sam?",cn:"山姆，你几点吃午饭？"},{speaker:"Sam",voice:"b",en:"At twelve. Then I go to a school club.",cn:"十二点。然后我去参加学校社团。"},{speaker:"Lily",voice:"a",en:"What time do you play sports?",cn:"你几点做运动？"},{speaker:"Sam",voice:"b",en:"I play sports for half an hour after school.",cn:"放学后我做半小时运动。"},{speaker:"Lily",voice:"a",en:"What time do you have dinner?",cn:"你几点吃晚饭？"},{speaker:"Sam",voice:"b",en:"At six. After that, I read books and watch TV. I pack my schoolbag at nine.",cn:"六点。之后我看书、看电视。九点收拾书包。"}]},{unitId:"x3u4",scene:"Break-time game",sceneCn:"课间游戏",bigQuestion:"How do we join a game politely?",bigQuestionCn:"怎样礼貌地加入游戏？",tip:"先问 Do you want to join us?，想加入就说 I’d love to! 或 Can I have a turn?",dialogue:[{speaker:"Tom",voice:"b",en:"Do you want to join us? We’re playing a game.",cn:"你想加入我们吗？我们在玩游戏。"},{speaker:"Mia",voice:"a",en:"I’d love to! Can I have a turn?",cn:"我很想！能轮到我吗？"},{speaker:"Tom",voice:"b",en:"Sure. You’re next after Amy.",cn:"当然。你在艾米之后。"},{speaker:"Mia",voice:"a",en:"What should I do first?",cn:"我首先该做什么？"},{speaker:"Tom",voice:"b",en:"Try to catch the ball. It’s fun!",cn:"试着接球。很好玩！"},{speaker:"Mia",voice:"a",en:"OK. I’ll try my best!",cn:"好的。我会尽力！"}]},{unitId:"x3u5",scene:"Our class poster",sceneCn:"班级海报",bigQuestion:"What rules make a good classroom?",bigQuestionCn:"好的教室需要哪些约定？",tip:"提建议用 We should ...，说喜欢某条规则用 I like ...。",dialogue:[{speaker:"Ms Huang",voice:"a",en:"Let’s make a poster for our classroom.",cn:"我们来为教室做一张海报吧。"},{speaker:"Ben",voice:"b",en:"Good idea! What are the rules in our class?",cn:"好主意！我们班有哪些规则？"},{speaker:"Ms Huang",voice:"a",en:"We should listen carefully and take turns to speak.",cn:"我们应该仔细听，轮流发言。"},{speaker:"Amy",voice:"a",en:"And we should put away our things.",cn:"我们还应该收拾好自己的东西。"},{speaker:"Ben",voice:"b",en:"I like “Give a helping hand”.",cn:"我喜欢“伸出援手”这一条。"},{speaker:"Ms Huang",voice:"a",en:"Me too! Let’s do our best every day.",cn:"我也是！让我们每天尽最大努力。"}]},{unitId:"x3u6",scene:"Duty day",sceneCn:"值日日",bigQuestion:"How do we talk about class jobs?",bigQuestionCn:"怎样谈论班级岗位？",tip:"问想当什么用 What do you want to be?，回答用 I want to be ...。",dialogue:[{speaker:"Mr Chen",voice:"b",en:"It’s our duty day. What do you want to be, Ben?",cn:"今天是我们的值日日。本，你想当什么？"},{speaker:"Ben",voice:"b",en:"I want to be a line leader. I can lead the way.",cn:"我想当列队小帮手。我可以带路。"},{speaker:"Mr Chen",voice:"b",en:"Good. What about you, Mia?",cn:"很好。你呢，米娅？"},{speaker:"Mia",voice:"a",en:"I want to be a lunch helper. I can hand out food.",cn:"我想当午饭小帮手。我可以分发食物。"},{speaker:"Mr Chen",voice:"b",en:"And you, Tom?",cn:"你呢，汤姆？"},{speaker:"Tom",voice:"b",en:"I want to be a teacher helper and put away books.",cn:"我想当老师小帮手，整理书本。"},{speaker:"Mr Chen",voice:"b",en:"Great! Every job is important.",cn:"太棒了！每个岗位都很重要。"}]},{unitId:"x3u7",scene:"School rules",sceneCn:"校园规则",bigQuestion:"What should we do at school?",bigQuestionCn:"在学校应该怎样做？",tip:"用 We should ... 说规则；做错时说 Oh, sorry!，回应 It’s okay。",dialogue:[{speaker:"Ms Huang",voice:"a",en:"What should we do at school?",cn:"在学校我们应该怎么做？"},{speaker:"Leo",voice:"b",en:"We should keep to the right in the hallway.",cn:"在走廊里我们应该靠右走。"},{speaker:"Ms Huang",voice:"a",en:"Yes. And in the library?",cn:"对。那在图书馆呢？"},{speaker:"Nina",voice:"a",en:"We should keep our voice down.",cn:"我们应该小声说话。"},{speaker:"Leo",voice:"b",en:"Oh, sorry! I forgot to get in line.",cn:"哦，抱歉！我忘记排队了。"},{speaker:"Ms Huang",voice:"a",en:"It’s okay. After Chinese and Maths, we have Art and PE.",cn:"没关系。语文和数学课后，我们上美术和体育课。"},{speaker:"Nina",voice:"a",en:"Let’s get in line now.",cn:"我们现在排队吧。"}]},{unitId:"x3u8",scene:"A polite afternoon",sceneCn:"礼貌的下午",bigQuestion:"How do we ask for help politely?",bigQuestionCn:"怎样礼貌地请人帮忙？",tip:"请求帮忙用 Can you help me, please?，得到帮助后说 Thank you。",dialogue:[{speaker:"Ms Lin",voice:"a",en:"What a music class! Can you help me, please?",cn:"这节音乐课真热闹！你能帮我一下吗？"},{speaker:"Ben",voice:"b",en:"Sure. What can I do?",cn:"当然。我能做什么？"},{speaker:"Ms Lin",voice:"a",en:"Please close the window, and turn on the lights and the fan.",cn:"请关上窗户，再打开灯和风扇。"},{speaker:"Ben",voice:"b",en:"OK. Look, the piano and the blackboard are clean.",cn:"好的。看，钢琴和黑板都干净了。"},{speaker:"Ms Lin",voice:"a",en:"Thank you. Please put the chair under the desk.",cn:"谢谢你。请把椅子放到书桌下面。"},{speaker:"Ben",voice:"b",en:"Of course. You’re welcome!",cn:"好的。不客气！"},{speaker:"Ms Lin",voice:"a",en:"You are so polite, Ben.",cn:"你真有礼貌，本。"}]},{unitId:"g1au1",scene:"At the school gate",sceneCn:"在校门口",bigQuestion:"How do we greet a new friend?",bigQuestionCn:"怎样和新朋友打招呼？",tip:"看着对方，笑着说 Hello，再说出自己的名字。",dialogue:[{speaker:"Mia",voice:"a",en:"Hello! I'm Mia. What's your name?",cn:"你好！我是米娅。你叫什么名字？"},{speaker:"Ben",voice:"b",en:"Hi, Mia! I'm Ben.",cn:"嗨，米娅！我是本。"},{speaker:"Mia",voice:"a",en:"Good morning, Ben!",cn:"早上好，本！"},{speaker:"Ben",voice:"b",en:"Good morning! Let's go to class.",cn:"早上好！我们去上课吧。"}]},{unitId:"g1au2",scene:"At home",sceneCn:"在家里",bigQuestion:"How do we introduce our family?",bigQuestionCn:"怎样用英语介绍家人？",tip:"指着照片说 This is ...，再告诉对方他是谁。",dialogue:[{speaker:"Mia",voice:"a",en:"Look! This is my family.",cn:"看！这是我的家人。"},{speaker:"Ben",voice:"b",en:"Who is she?",cn:"她是谁？"},{speaker:"Mia",voice:"a",en:"She is my mother. This is my father.",cn:"她是我的妈妈。这是我的爸爸。"},{speaker:"Ben",voice:"b",en:"Is this your brother?",cn:"这是你的兄弟吗？"},{speaker:"Mia",voice:"a",en:"Yes! He is my little brother. I love my family.",cn:"是的！他是我的弟弟。我爱我的家人。"}]},{unitId:"g1au3",scene:"A drawing lesson",sceneCn:"美术课",bigQuestion:"How do we talk about colours?",bigQuestionCn:"怎样说身边的颜色？",tip:"问颜色用 What colour is it?，回答用 It's ...。",dialogue:[{speaker:"Ben",voice:"a",en:"Look at my kite!",cn:"看我的风筝！"},{speaker:"Mia",voice:"b",en:"What colour is it?",cn:"它是什么颜色？"},{speaker:"Ben",voice:"a",en:"It's red and yellow.",cn:"它是红色和黄色的。"},{speaker:"Mia",voice:"b",en:"I like red. My ball is blue.",cn:"我喜欢红色。我的球是蓝色的。"},{speaker:"Ben",voice:"a",en:"Blue is nice too!",cn:"蓝色也很好看！"}]},{unitId:"g1au4",scene:"A birthday table",sceneCn:"生日桌旁",bigQuestion:"How do we count things in English?",bigQuestionCn:"怎样用英语数数？",tip:"问数量用 How many，回答时说出数字和物品。",dialogue:[{speaker:"Mia",voice:"a",en:"Look at the balloons!",cn:"看这些气球！"},{speaker:"Ben",voice:"b",en:"How many balloons?",cn:"有多少个气球？"},{speaker:"Mia",voice:"a",en:"One, two, three, four, five, six!",cn:"一、二、三、四、五、六！"},{speaker:"Ben",voice:"b",en:"Six balloons! I have six too.",cn:"六个气球！我也有六个。"}]},{unitId:"g1au5",scene:"At the pet corner",sceneCn:"宠物角",bigQuestion:"What can animals do?",bigQuestionCn:"动物们会做什么？",tip:"用 It can ... 说出动物的本领，如 run、sing、swim。",dialogue:[{speaker:"Ben",voice:"a",en:"Look at the bird!",cn:"看那只鸟！"},{speaker:"Mia",voice:"b",en:"It can sing. I have a cat at home.",cn:"它会唱歌。我家里有一只猫。"},{speaker:"Ben",voice:"a",en:"My dog can run fast.",cn:"我的狗跑得很快。"},{speaker:"Mia",voice:"b",en:"Look! The rabbit can jump.",cn:"看！兔子会跳。"},{speaker:"Ben",voice:"a",en:"I love animals!",cn:"我爱动物！"}]},{unitId:"g1au6",scene:"A game of Simon says",sceneCn:"Simon says 游戏",bigQuestion:"How do we name parts of our body?",bigQuestionCn:"怎样用英语说身体部位？",tip:"听清 Touch your ...，再快速指出对应部位。",dialogue:[{speaker:"Mia",voice:"a",en:"Let's play Simon says!",cn:"我们来玩 Simon says 吧！"},{speaker:"Ben",voice:"b",en:"OK! Touch your nose.",cn:"好！摸摸你的鼻子。"},{speaker:"Mia",voice:"a",en:"This is my nose. Touch your ears!",cn:"这是我的鼻子。摸摸你的耳朵！"},{speaker:"Ben",voice:"b",en:"My ears! Now touch your foot.",cn:"我的耳朵！现在摸摸你的脚。"},{speaker:"Mia",voice:"a",en:"Ha! This game is fun.",cn:"哈！这个游戏真好玩。"}]},{unitId:"g1bu1",scene:"In the playroom",sceneCn:"在游戏室",bigQuestion:"How do we share our toys?",bigQuestionCn:"怎样和别人分享玩具？",tip:"想玩别人的玩具，先说 Can I play with ...?，再道谢。",dialogue:[{speaker:"Ben",voice:"a",en:"Look at my new car!",cn:"看我的新小汽车！"},{speaker:"Mia",voice:"b",en:"It's nice. Can I play with it?",cn:"真好看。我可以玩一下吗？"},{speaker:"Ben",voice:"a",en:"Sure! Here you are.",cn:"当然！给你。"},{speaker:"Mia",voice:"b",en:"Thank you! Let's play together.",cn:"谢谢你！我们一起玩吧。"}]},{unitId:"g1bu2",scene:"At the breakfast table",sceneCn:"早餐桌旁",bigQuestion:"What do you like for breakfast?",bigQuestionCn:"你早餐喜欢吃什么？",tip:"用 I like ... 说出喜欢的食物，用 Have some ... 请别人吃。",dialogue:[{speaker:"Mum",voice:"a",en:"What do you want for breakfast?",cn:"你早餐想吃什么？"},{speaker:"Mia",voice:"b",en:"I want an egg and some milk.",cn:"我想要一个鸡蛋和一些牛奶。"},{speaker:"Mum",voice:"a",en:"Here you are. Have some bread too.",cn:"给你。再吃些面包吧。"},{speaker:"Mia",voice:"b",en:"Thank you! I like bread.",cn:"谢谢！我喜欢面包。"}]},{unitId:"g1bu3",scene:"In the classroom",sceneCn:"在教室里",bigQuestion:"How do we find our school things?",bigQuestionCn:"怎样找到自己的学习用品？",tip:"找不到东西时问 Where is my ...?，再用 in / on / under 回答。",dialogue:[{speaker:"Ben",voice:"a",en:"Where is my ruler?",cn:"我的尺子在哪里？"},{speaker:"Mia",voice:"b",en:"Is it on your desk?",cn:"在你的课桌上吗？"},{speaker:"Ben",voice:"a",en:"No. Oh, it's in my bag!",cn:"不在。哦，它在我的书包里！"},{speaker:"Mia",voice:"b",en:"Look! My book is under the chair.",cn:"看！我的书在椅子下面。"}]},{unitId:"g1bu4",scene:"Looking out of the window",sceneCn:"望向窗外",bigQuestion:"How do we talk about the weather?",bigQuestionCn:"怎样谈论天气？",tip:"说天气用 It's + 天气词，如 It's sunny。",dialogue:[{speaker:"Mia",voice:"a",en:"Look outside! It's sunny.",cn:"看外面！天气晴朗。"},{speaker:"Ben",voice:"b",en:"Great! Let's play in the park.",cn:"太好了！我们去公园玩吧。"},{speaker:"Mia",voice:"a",en:"Wait! It's windy too.",cn:"等等！还刮风呢。"},{speaker:"Ben",voice:"b",en:"Perfect! We can fly a kite.",cn:"太棒了！我们可以放风筝。"}]},{unitId:"g1bu5",scene:"In the playground",sceneCn:"在操场上",bigQuestion:"What can you do?",bigQuestionCn:"你会做什么？",tip:"用 I can ... 说出自己的本领，用 Can you ...? 问别人。",dialogue:[{speaker:"Ben",voice:"a",en:"I can run fast. Can you run?",cn:"我能跑得很快。你会跑吗？"},{speaker:"Mia",voice:"b",en:"Yes, I can. I can jump too.",cn:"会呀。我还会跳。"},{speaker:"Ben",voice:"a",en:"Can you swim?",cn:"你会游泳吗？"},{speaker:"Mia",voice:"b",en:"No, I can't. But I can sing and dance.",cn:"不会。但我会唱歌和跳舞。"},{speaker:"Ben",voice:"a",en:"Great! Let's sing together.",cn:"太好了！我们一起唱歌吧。"}]},{unitId:"g1bu6",scene:"At Mia's birthday party",sceneCn:"米娅的生日聚会",bigQuestion:"How do we celebrate a birthday?",bigQuestionCn:"怎样庆祝生日？",tip:"送礼物时说 This is for you.，对方回答 Thank you!。",dialogue:[{speaker:"Ben",voice:"a",en:"Happy birthday, Mia!",cn:"生日快乐，米娅！"},{speaker:"Mia",voice:"b",en:"Thank you, Ben!",cn:"谢谢你，本！"},{speaker:"Ben",voice:"a",en:"This gift is for you.",cn:"这份礼物是给你的。"},{speaker:"Mia",voice:"b",en:"A kite! I love it. Let's have cake.",cn:"一只风筝！我很喜欢。我们吃蛋糕吧。"},{speaker:"Ben",voice:"a",en:"OK! The candles are ready.",cn:"好！蜡烛准备好啦。"}]},{unitId:"g2au1",scene:"A new classmate",sceneCn:"新同学来了",bigQuestion:"How do we talk about a friend?",bigQuestionCn:"怎样介绍自己的朋友？",tip:"先用 He / She is ... 说特点，再说你们一起做什么。",dialogue:[{speaker:"Ben",voice:"a",en:"Who is that girl?",cn:"那个女孩是谁？"},{speaker:"Mia",voice:"b",en:"She is Amy. She is my friend.",cn:"她是艾米，是我的朋友。"},{speaker:"Ben",voice:"a",en:"She is tall and kind.",cn:"她又高又友善。"},{speaker:"Mia",voice:"b",en:"Yes! She can draw well. Let's play with her.",cn:"对！她画画很好。我们和她一起玩吧。"}]},{unitId:"g2au2",scene:"Showing a new friend around",sceneCn:"带新朋友参观",bigQuestion:"How do we introduce our school?",bigQuestionCn:"怎样介绍自己的学校？",tip:"说 This is our ...，再补充我们在这里做什么。",dialogue:[{speaker:"Mia",voice:"a",en:"Welcome to our school, Amy!",cn:"艾米，欢迎来到我们的学校！"},{speaker:"Amy",voice:"b",en:"Wow! Where is your class?",cn:"哇！你的班级在哪里？"},{speaker:"Mia",voice:"a",en:"This is our class. We read in the library too.",cn:"这是我们的班级。我们也在图书馆看书。"},{speaker:"Amy",voice:"b",en:"I like the playground.",cn:"我喜欢这个操场。"},{speaker:"Mia",voice:"a",en:"Me too! We run here every day.",cn:"我也是！我们每天在这里跑步。"}]},{unitId:"g2au3",scene:"Talking about a school day",sceneCn:"聊一聊上学日",bigQuestion:"What do you do in a day?",bigQuestionCn:"你一天都做些什么？",tip:"用 at + 时间 说清楚每件事发生在几点。",dialogue:[{speaker:"Amy",voice:"a",en:"What time do you get up?",cn:"你几点起床？"},{speaker:"Ben",voice:"b",en:"I get up at seven. Then I have breakfast.",cn:"我七点起床，然后吃早餐。"},{speaker:"Amy",voice:"a",en:"What do you do in the afternoon?",cn:"你下午做什么？"},{speaker:"Ben",voice:"b",en:"I play football. In the evening, I read books.",cn:"我踢足球。晚上我看书。"},{speaker:"Amy",voice:"a",en:"I sleep at nine. Good night!",cn:"我九点睡觉。晚安！"}]},{unitId:"g2au4",scene:"At the fruit shop",sceneCn:"在水果店",bigQuestion:"How do we buy fruit?",bigQuestionCn:"怎样用英语买水果？",tip:"问喜好用 Do you like ...?，数量用 How many ...?",dialogue:[{speaker:"Mum",voice:"a",en:"Let's buy some fruit.",cn:"我们买些水果吧。"},{speaker:"Ben",voice:"b",en:"I like oranges. Do you like grapes, Mum?",cn:"我喜欢橙子。妈妈，你喜欢葡萄吗？"},{speaker:"Mum",voice:"a",en:"Yes, I do. How many peaches do you want?",cn:"喜欢。你想要几个桃子？"},{speaker:"Ben",voice:"b",en:"Three, please. And one big watermelon!",cn:"三个。还要一个大西瓜！"}]},{unitId:"g2au5",scene:"Getting ready for a party",sceneCn:"准备参加聚会",bigQuestion:"How do we talk about clothes?",bigQuestionCn:"怎样谈论穿着？",tip:"说自己穿什么用 I'm wearing ...，问是谁的用 Whose ... is this?",dialogue:[{speaker:"Mia",voice:"a",en:"I'm wearing my red dress today.",cn:"我今天穿我的红裙子。"},{speaker:"Ben",voice:"b",en:"It's pretty! I'm wearing a white shirt.",cn:"真漂亮！我穿一件白衬衫。"},{speaker:"Mia",voice:"a",en:"Whose hat is this?",cn:"这是谁的帽子？"},{speaker:"Ben",voice:"b",en:"It's my sister's. Put on your shoes. Let's go!",cn:"是我妹妹的。穿上你的鞋子，我们走吧！"}]},{unitId:"g2au6",scene:"A walk in the park",sceneCn:"公园散步",bigQuestion:"What can we see in the park?",bigQuestionCn:"在公园里能看到什么？",tip:"一个东西用 There is，多个东西用 There are。",dialogue:[{speaker:"Ben",voice:"a",en:"What a big park!",cn:"好大的公园！"},{speaker:"Mia",voice:"b",en:"There are many flowers. I can see a lake too.",cn:"这里有很多花，我还能看见一个湖。"},{speaker:"Ben",voice:"a",en:"There is a boat on the lake.",cn:"湖上有一只小船。"},{speaker:"Mia",voice:"b",en:"Let's sit on the grass and draw the trees.",cn:"我们坐在草地上画树吧。"}]},{unitId:"g2bu1",scene:"A busy morning",sceneCn:"忙碌的早晨",bigQuestion:"How do we tell the time?",bigQuestionCn:"怎样用英语说时间？",tip:"整点用 o'clock，半点用 half past ...。",dialogue:[{speaker:"Mum",voice:"a",en:"Ben, get up! It's seven o'clock.",cn:"本，起床！七点了。"},{speaker:"Ben",voice:"b",en:"What time is it?",cn:"现在几点？"},{speaker:"Mum",voice:"a",en:"It's half past seven. It's time to go to school!",cn:"七点半了，该去上学了！"},{speaker:"Ben",voice:"b",en:"Oh no! I'm late. Hurry up!",cn:"哦不！我迟到了。快点！"}]},{unitId:"g2bu2",scene:"Visiting Mia's home",sceneCn:"参观米娅的家",bigQuestion:"How do we talk about rooms at home?",bigQuestionCn:"怎样介绍家里的房间？",tip:"介绍房间用 This is our ...，说里面有什么用 There is ...",dialogue:[{speaker:"Mia",voice:"a",en:"Welcome to my home!",cn:"欢迎来我家！"},{speaker:"Ben",voice:"b",en:"Your home is nice. Where is your bedroom?",cn:"你家真不错。你的卧室在哪里？"},{speaker:"Mia",voice:"a",en:"This is my bedroom. There is a big bed and a desk.",cn:"这是我的卧室，里面有一张大床和一张书桌。"},{speaker:"Ben",voice:"b",en:"Great! And this is the living room?",cn:"真棒！这是客厅吗？"},{speaker:"Mia",voice:"a",en:"Yes. Mum is in the kitchen. Let's read here.",cn:"是的。妈妈在厨房，我们在这里看书吧。"}]},{unitId:"g2bu3",scene:"Sports day",sceneCn:"运动会上",bigQuestion:"How do we talk about sports?",bigQuestionCn:"怎样谈论运动？",tip:"说喜欢某项运动用 I like playing ...，为队伍加油说 Come on!",dialogue:[{speaker:"Ben",voice:"a",en:"It's sports day! I like playing football.",cn:"今天是运动会！我喜欢踢足球。"},{speaker:"Mia",voice:"b",en:"I like basketball. Let's watch the race.",cn:"我喜欢篮球。我们去看赛跑吧。"},{speaker:"Ben",voice:"a",en:"Come on, Amy! Run fast!",cn:"加油，艾米！跑快点！"},{speaker:"Mia",voice:"b",en:"She wins! Our team is the best!",cn:"她赢了！我们的队伍最棒！"}]},{unitId:"g2bu4",scene:"A lesson about jobs",sceneCn:"职业课",bigQuestion:"What do people do for work?",bigQuestionCn:"人们做什么工作？",tip:"问职业用 What does he / she do?，回答用 He / She is a ...",dialogue:[{speaker:"Miss Li",voice:"a",en:"What does your father do, Ben?",cn:"本，你爸爸是做什么的？"},{speaker:"Ben",voice:"b",en:"He is a doctor. He helps sick people.",cn:"他是医生，帮助生病的人。"},{speaker:"Miss Li",voice:"a",en:"And your mother, Mia?",cn:"米娅，你妈妈呢？"},{speaker:"Mia",voice:"b",en:"She is a teacher. I want to be a teacher too!",cn:"她是老师。我也想成为一名老师！"}]},{unitId:"g2bu5",scene:"Talking about seasons",sceneCn:"聊季节",bigQuestion:"What is your favourite season?",bigQuestionCn:"你最喜欢哪个季节？",tip:"说季节用 In + 季节，再说天气和能做的事。",dialogue:[{speaker:"Mia",voice:"a",en:"What's your favourite season, Ben?",cn:"本，你最喜欢哪个季节？"},{speaker:"Ben",voice:"b",en:"I like winter. It's cold and I can see snow.",cn:"我喜欢冬天，很冷，还能看到雪。"},{speaker:"Mia",voice:"a",en:"I like spring. It's warm and the flowers are beautiful.",cn:"我喜欢春天，很温暖，花也很美。"},{speaker:"Ben",voice:"b",en:"Summer is fun too. We can swim!",cn:"夏天也很有趣，我们可以游泳！"}]},{unitId:"g2bu6",scene:"Talking about festivals",sceneCn:"聊节日",bigQuestion:"How do we celebrate festivals?",bigQuestionCn:"我们怎样庆祝节日？",tip:"介绍节日时说清时间、食物和活动。",dialogue:[{speaker:"Amy",voice:"a",en:"What's your favourite festival, Ben?",cn:"本，你最喜欢什么节日？"},{speaker:"Ben",voice:"b",en:"I like the Spring Festival. We have a big dinner.",cn:"我喜欢春节，我们会吃一顿丰盛的年夜饭。"},{speaker:"Amy",voice:"a",en:"We eat mooncakes at Mid-Autumn. The lanterns are beautiful.",cn:"中秋节我们吃月饼，灯笼很美。"},{speaker:"Ben",voice:"b",en:"Happy new year, Amy!",cn:"新年快乐，艾米！"},{speaker:"Amy",voice:"a",en:"Happy new year!",cn:"新年快乐！"}]},{unitId:"g4au1",scene:"Our new classroom",sceneCn:"我们的新教室",bigQuestion:"What is in our classroom?",bigQuestionCn:"我们的教室里有什么？",tip:"描述教室时，先用 There is / are 说有什么，再用位置词说在哪里。",dialogue:[{speaker:"Ben",voice:"a",en:"Look at our new classroom!",cn:"看我们的新教室！"},{speaker:"Mia",voice:"b",en:"There are two big windows and a new computer.",cn:"有两扇大窗户和一台新电脑。"},{speaker:"Ben",voice:"a",en:"Where is the computer?",cn:"电脑在哪里？"},{speaker:"Mia",voice:"b",en:"It's next to the door. There is a picture on the wall too.",cn:"在门旁边。墙上还有一幅画。"},{speaker:"Ben",voice:"a",en:"Our classroom is clean and bright. I like it!",cn:"我们的教室又干净又明亮，我喜欢！"}]},{unitId:"g4au2",scene:"At the lost and found",sceneCn:"在失物招领处",bigQuestion:"How do we find lost things?",bigQuestionCn:"怎样找回丢失的东西？",tip:"问物主用 Whose ... is this?，回答可以用 mine / hers / his。",dialogue:[{speaker:"Ben",voice:"a",en:"I can't find my key. Is it in your bag?",cn:"我找不到钥匙了。在你的包里吗？"},{speaker:"Mia",voice:"b",en:"No. Whose schoolbag is this?",cn:"不在。这是谁的书包？"},{speaker:"Ben",voice:"a",en:"It's Amy's. Look, my key is under the desk!",cn:"是艾米的。看，我的钥匙在桌子下面！"},{speaker:"Mia",voice:"b",en:"Great! And here is her notebook.",cn:"太好了！她的笔记本在这里。"},{speaker:"Ben",voice:"a",en:"Let's give it back to her.",cn:"我们还给她吧。"}]},{unitId:"g4au3",scene:"A new friend in class",sceneCn:"班里的新朋友",bigQuestion:"How do we describe a friend?",bigQuestionCn:"怎样描述一个朋友？",tip:"从外貌、性格和爱好三个方面介绍，会更清楚。",dialogue:[{speaker:"Mia",voice:"a",en:"This is our new classmate, Jack.",cn:"这是我们的新同学杰克。"},{speaker:"Ben",voice:"b",en:"Hi, Jack! You are tall and strong.",cn:"嗨，杰克！你又高又强壮。"},{speaker:"Jack",voice:"a",en:"Thanks! I like science and music.",cn:"谢谢！我喜欢科学和音乐。"},{speaker:"Mia",voice:"b",en:"Jack is quiet, but he always helps others.",cn:"杰克很安静，但他总是帮助别人。"},{speaker:"Ben",voice:"a",en:"Great! Let's play basketball together.",cn:"太好了！我们一起打篮球吧。"}]},{unitId:"g4au4",scene:"A home tour",sceneCn:"参观我的家",bigQuestion:"How do we describe our home?",bigQuestionCn:"怎样介绍自己的家？",tip:"先带路说 This way, please.，再介绍每个房间里有什么。",dialogue:[{speaker:"Mia",voice:"a",en:"Come in! Let me show you our home.",cn:"请进！让我带你看看我们的家。"},{speaker:"Ben",voice:"b",en:"Wow, the living room is big. The sofa is so soft.",cn:"哇，客厅真大。沙发好软。"},{speaker:"Mia",voice:"a",en:"The clock is on the wall. My bedroom is upstairs.",cn:"钟在墙上。我的卧室在楼上。"},{speaker:"Ben",voice:"b",en:"Your room is tidy. Is that a new bed?",cn:"你的房间真整洁。那是新床吗？"},{speaker:"Mia",voice:"a",en:"Yes! And my phone is on the table.",cn:"是的！我的电话在桌子上。"}]},{unitId:"g4au5",scene:"At the dinner table",sceneCn:"晚餐桌旁",bigQuestion:"How do we invite others to eat?",bigQuestionCn:"怎样礼貌地请人吃饭？",tip:"用 Would you like ...? 邀请，用 Yes, please. 或 No, thanks. 回应。",dialogue:[{speaker:"Mum",voice:"a",en:"Dinner is ready! Come and eat.",cn:"晚饭好了！来吃饭吧。"},{speaker:"Ben",voice:"b",en:"I'm hungry. The noodles smell good.",cn:"我饿了。面条闻起来真香。"},{speaker:"Mum",voice:"a",en:"Would you like some beef and vegetables?",cn:"你想要一些牛肉和蔬菜吗？"},{speaker:"Ben",voice:"b",en:"Yes, please. And some soup too.",cn:"好的，谢谢。还要一些汤。"},{speaker:"Mum",voice:"a",en:"Here is your bowl and chopsticks.",cn:"这是你的碗和筷子。"}]},{unitId:"g4au6",scene:"A lesson about dreams",sceneCn:"梦想课",bigQuestion:"What do you want to be?",bigQuestionCn:"你长大后想做什么？",tip:"说理想时，用 I want to be ... because ... 说明原因。",dialogue:[{speaker:"Miss Li",voice:"a",en:"What's your dream job, Ben?",cn:"本，你梦想的工作是什么？"},{speaker:"Ben",voice:"b",en:"I want to be a football player.",cn:"我想成为一名足球运动员。"},{speaker:"Miss Li",voice:"a",en:"Why do you like it?",cn:"你为什么喜欢这份工作？"},{speaker:"Ben",voice:"b",en:"Because I love sports and I can work with my team.",cn:"因为我热爱运动，也能和团队一起努力。"},{speaker:"Mia",voice:"a",en:"I want to be a doctor. I want to help sick people.",cn:"我想当医生，帮助生病的人。"}]},{unitId:"g4bu1",scene:"A school tour",sceneCn:"校园参观",bigQuestion:"How do we show visitors around our school?",bigQuestionCn:"怎样带客人参观学校？",tip:"带路说 This way, please.，介绍地点说 It's on the ... floor.",dialogue:[{speaker:"Mia",voice:"a",en:"Welcome to our school! This way, please.",cn:"欢迎来到我们学校！这边请。"},{speaker:"Visitor",voice:"b",en:"Where is the library?",cn:"图书馆在哪里？"},{speaker:"Mia",voice:"a",en:"It's on the second floor, next to the music room.",cn:"在二楼，音乐室旁边。"},{speaker:"Visitor",voice:"b",en:"And what is on the first floor?",cn:"那一楼有什么？"},{speaker:"Mia",voice:"a",en:"The office and the art room. The gym is behind the playground.",cn:"办公室和美术室。体育馆在操场后面。"}]},{unitId:"g4bu2",scene:"Talking about a timetable",sceneCn:"聊课程表",bigQuestion:"How do we talk about our timetable?",bigQuestionCn:"怎样谈论课程安排？",tip:"问时间用 What time do you ...?，回答用 at + 时间。",dialogue:[{speaker:"Ben",voice:"a",en:"What time do you get up, Mia?",cn:"米娅，你几点起床？"},{speaker:"Mia",voice:"b",en:"I get up at six forty. Then I have breakfast.",cn:"我六点四十起床，然后吃早餐。"},{speaker:"Ben",voice:"a",en:"What time is English class?",cn:"英语课几点？"},{speaker:"Mia",voice:"b",en:"At eight thirty. We have PE class at two.",cn:"八点半。我们两点上体育课。"},{speaker:"Ben",voice:"a",en:"Great! I go to bed at nine thirty.",cn:"真好！我九点半睡觉。"}]},{unitId:"g4bu3",scene:"Watching the weather forecast",sceneCn:"看天气预报",bigQuestion:"How do we talk about the weather?",bigQuestionCn:"怎样谈论天气和温度？",tip:"说天气用 What's the weather like?，说温度用 It's ... degrees。",dialogue:[{speaker:"Mum",voice:"a",en:"What's the weather like today?",cn:"今天天气怎么样？"},{speaker:"Ben",voice:"b",en:"It's cloudy and cool. It's twenty degrees.",cn:"多云，凉爽，二十度。"},{speaker:"Mum",voice:"a",en:"The forecast says it will rain in the afternoon.",cn:"预报说下午会下雨。"},{speaker:"Ben",voice:"b",en:"Then I need my umbrella and raincoat.",cn:"那我需要雨伞和雨衣。"},{speaker:"Mum",voice:"a",en:"Good boy. Have a nice day at school!",cn:"好孩子。在学校过得愉快！"}]},{unitId:"g4bu4",scene:"A visit to the farm",sceneCn:"参观农场",bigQuestion:"What can we see on a farm?",bigQuestionCn:"在农场能看到什么？",tip:"用 There are ... 说多个动物或蔬菜，用 How many 问数量。",dialogue:[{speaker:"Uncle",voice:"a",en:"Welcome to my farm!",cn:"欢迎来到我的农场！"},{speaker:"Ben",voice:"b",en:"Wow! How many horses are there?",cn:"哇！有多少匹马？"},{speaker:"Uncle",voice:"a",en:"There are three horses and five cows.",cn:"有三匹马和五头奶牛。"},{speaker:"Mia",voice:"b",en:"The sheep is so cute. Look at the hens!",cn:"绵羊真可爱。看那些母鸡！"},{speaker:"Uncle",voice:"a",en:"You can pick some tomatoes and carrots.",cn:"你们可以摘些西红柿和胡萝卜。"}]},{unitId:"g4bu5",scene:"Choosing clothes for a trip",sceneCn:"为旅行选衣服",bigQuestion:"How do we choose clothes for the weather?",bigQuestionCn:"怎样根据天气选衣服？",tip:"给建议用 You should wear ...，再说为什么。",dialogue:[{speaker:"Mum",voice:"a",en:"We are going to Beijing. It's cold there.",cn:"我们要去北京，那里很冷。"},{speaker:"Ben",voice:"b",en:"Should I take my jacket?",cn:"我要带夹克吗？"},{speaker:"Mum",voice:"a",en:"Yes. You should wear a sweater and gloves too.",cn:"要。你还应该穿毛衣、戴手套。"},{speaker:"Mia",voice:"b",en:"I want to take my skirt and shorts.",cn:"我想带短裙和短裤。"},{speaker:"Mum",voice:"a",en:"Not for this trip! It's winter in Beijing.",cn:"这次不行！北京是冬天。"}]},{unitId:"g4bu6",scene:"At a clothes shop",sceneCn:"在服装店",bigQuestion:"How do we buy clothes?",bigQuestionCn:"怎样用英语买衣服？",tip:"问价格用 How much is it?，想试穿用 Can I try it on?",dialogue:[{speaker:"Shop assistant",voice:"a",en:"Can I help you?",cn:"需要帮忙吗？"},{speaker:"Mum",voice:"b",en:"Yes, I'd like a T-shirt for my son.",cn:"是的，我想给我儿子买一件 T 恤。"},{speaker:"Shop assistant",voice:"a",en:"What size does he wear?",cn:"他穿什么尺码？"},{speaker:"Mum",voice:"b",en:"Size 10. How much is this blue one?",cn:"十码。这件蓝色的多少钱？"},{speaker:"Shop assistant",voice:"a",en:"It's forty yuan. It's cheap and nice.",cn:"四十元，又便宜又好看。"}]},{unitId:"g5au1",scene:"A hobby club",sceneCn:"爱好社团",bigQuestion:"What do you like doing in your free time?",bigQuestionCn:"你空闲时间喜欢做什么？",tip:"介绍爱好用 My hobby is ...，再说为什么喜欢。",dialogue:[{speaker:"Amy",voice:"a",en:"What do you do in your free time, Ben?",cn:"本，你空闲时间做什么？"},{speaker:"Ben",voice:"b",en:"My hobby is painting. I paint every weekend.",cn:"我的爱好是画画，每个周末都画。"},{speaker:"Amy",voice:"a",en:"How interesting! I like singing and dancing.",cn:"真有趣！我喜欢唱歌和跳舞。"},{speaker:"Ben",voice:"b",en:"Why do you like singing?",cn:"你为什么喜欢唱歌？"},{speaker:"Amy",voice:"a",en:"Because music makes me happy. Let's join the music club!",cn:"因为音乐让我快乐。我们加入音乐社团吧！"}]},{unitId:"g5au2",scene:"Talking about the week",sceneCn:"聊一周安排",bigQuestion:"How do we talk about our weekly routine?",bigQuestionCn:"怎样谈论一周的作息？",tip:"用 always、usually、often、sometimes、never 表示做事的频率。",dialogue:[{speaker:"Mia",voice:"a",en:"How often do you play football, Ben?",cn:"本，你多久踢一次足球？"},{speaker:"Ben",voice:"b",en:"I usually play on Saturday. Sometimes on Sunday too.",cn:"我通常星期六踢，有时星期天也踢。"},{speaker:"Mia",voice:"a",en:"I always read on weekdays. I never watch TV late.",cn:"我工作日总是看书，从不晚看电视。"},{speaker:"Ben",voice:"b",en:"You are busy! What do you do on weekends?",cn:"你真忙！周末做什么？"},{speaker:"Mia",voice:"a",en:"I often visit my grandparents. We cook together.",cn:"我经常去看望祖父母，我们一起做饭。"}]},{unitId:"g5au3",scene:"A family photo",sceneCn:"一张全家福",bigQuestion:"How do we introduce our big family?",bigQuestionCn:"怎样介绍大家庭？",tip:"介绍亲属用 This is my ...，再说你们一起做什么。",dialogue:[{speaker:"Amy",voice:"a",en:"Is this your family photo, Ben?",cn:"本，这是你的全家福吗？"},{speaker:"Ben",voice:"b",en:"Yes. These are my grandparents. This is my uncle.",cn:"是的。这是我的祖父母，这是我的叔叔。"},{speaker:"Amy",voice:"a",en:"Who is the girl next to you?",cn:"你旁边的女孩是谁？"},{speaker:"Ben",voice:"b",en:"She is my cousin. We play together every weekend.",cn:"她是我的表妹，我们每个周末一起玩。"},{speaker:"Amy",voice:"a",en:"Your family is big and warm!",cn:"你的家庭真大真温暖！"}]},{unitId:"g5au4",scene:"Planning a season trip",sceneCn:"计划季节出游",bigQuestion:"What can we do in different seasons?",bigQuestionCn:"不同季节可以做什么？",tip:"用 In + 季节 开头，再说天气和活动。",dialogue:[{speaker:"Ben",voice:"a",en:"Which season do you like best, Mia?",cn:"米娅，你最喜欢哪个季节？"},{speaker:"Mia",voice:"b",en:"I like spring best. It's warm. We can have a picnic.",cn:"我最喜欢春天，很温暖，我们可以野餐。"},{speaker:"Ben",voice:"a",en:"I like autumn. It's the harvest season.",cn:"我喜欢秋天，那是收获的季节。"},{speaker:"Mia",voice:"b",en:"Let's watch the sunrise on the mountain in autumn!",cn:"秋天我们去山上看日出吧！"},{speaker:"Ben",voice:"a",en:"Great! The sunset there is beautiful too.",cn:"太好了！那里的日落也很美。"}]},{unitId:"g5au5",scene:"Planning a holiday",sceneCn:"计划假期",bigQuestion:"How do we make a travel plan?",bigQuestionCn:"怎样制定旅行计划？",tip:"说计划用 We are going to ...，再说交通和住宿。",dialogue:[{speaker:"Mum",voice:"a",en:"Let's plan our holiday. We are going to Xiamen.",cn:"我们来计划假期吧。我们打算去厦门。"},{speaker:"Ben",voice:"b",en:"Great! We can visit the museum and the beach.",cn:"太好了！我们可以参观博物馆和去海滩。"},{speaker:"Mum",voice:"a",en:"I will buy the train tickets today.",cn:"我今天去买火车票。"},{speaker:"Ben",voice:"b",en:"And I will pack my suitcase!",cn:"我来收拾行李箱！"},{speaker:"Mum",voice:"a",en:"Don't forget your hat and camera.",cn:"别忘了帽子和相机。"}]},{unitId:"g5au6",scene:"A health talk",sceneCn:"健康讲座",bigQuestion:"How can we stay healthy?",bigQuestionCn:"怎样保持健康？",tip:"提建议用 We should ...，也可以说 It's good for ...",dialogue:[{speaker:"Doctor",voice:"a",en:"How often do you exercise, Ben?",cn:"本，你多久锻炼一次？"},{speaker:"Ben",voice:"b",en:"I play football twice a week.",cn:"我一周踢两次足球。"},{speaker:"Doctor",voice:"a",en:"Good! You should eat more vegetables and fruit.",cn:"很好！你应该多吃蔬菜和水果。"},{speaker:"Ben",voice:"b",en:"I like fruit. Is milk good for me?",cn:"我喜欢水果。牛奶对我有好处吗？"},{speaker:"Doctor",voice:"a",en:"Yes. And remember to sleep eight hours every night.",cn:"有好处。还要记得每晚睡八小时。"}]},{unitId:"g5bu1",scene:"A class meeting about rules",sceneCn:"规则主题班会",bigQuestion:"Why do we need rules?",bigQuestionCn:"我们为什么需要规则？",tip:"must 表示必须，should 表示应该，语气更委婉。",dialogue:[{speaker:"Miss Li",voice:"a",en:"What rules should we follow at school?",cn:"在学校我们应该遵守哪些规则？"},{speaker:"Ben",voice:"b",en:"We must stand in line and wait for our turn.",cn:"我们必须排队，等轮到自己。"},{speaker:"Mia",voice:"a",en:"We should keep quiet in the library.",cn:"在图书馆我们应该保持安静。"},{speaker:"Miss Li",voice:"b",en:"Good. What does the sign say?",cn:"很好。那个标志写的是什么？"},{speaker:"Ben",voice:"a",en:'It says "No running". We must stay safe.',cn:"写着“禁止奔跑”。我们必须注意安全。"}]},{unitId:"g5bu2",scene:"A walk in the nature park",sceneCn:"自然公园散步",bigQuestion:"What can we see in nature?",bigQuestionCn:"在大自然里能看到什么？",tip:"描述景色时，用 There is / are 加上方位和形容词。",dialogue:[{speaker:"Ben",voice:"a",en:"What a beautiful nature park!",cn:"多美的自然公园啊！"},{speaker:"Mia",voice:"b",en:"There is a high mountain and a long river.",cn:"这里有一座高山和一条长河。"},{speaker:"Ben",voice:"a",en:"Look! There is a small bridge over the river.",cn:"看！河上有一座小桥。"},{speaker:"Mia",voice:"b",en:"The forest is so green. The air is fresh.",cn:"森林真绿，空气真新鲜。"},{speaker:"Ben",voice:"a",en:"We should keep it clean and protect nature.",cn:"我们应该保持清洁，保护自然。"}]},{unitId:"g5bu3",scene:"A culture exchange day",sceneCn:"文化交流日",bigQuestion:"How do we introduce Chinese culture?",bigQuestionCn:"怎样介绍中国文化？",tip:"介绍文化时说清它是什么、在什么时候做、有什么意义。",dialogue:[{speaker:"Amy",voice:"a",en:"What is paper cutting?",cn:"什么是剪纸？"},{speaker:"Mia",voice:"b",en:"It's a traditional Chinese art. We use red paper.",cn:"它是中国传统艺术，我们用红纸。"},{speaker:"Amy",voice:"a",en:"It looks difficult. Do you practise it?",cn:"看起来很难。你练习吗？"},{speaker:"Mia",voice:"b",en:"Yes, my grandma teaches me. At the Spring Festival, we put it on the window.",cn:"练，我奶奶教我。春节时我们会把它贴在窗户上。"},{speaker:"Amy",voice:"a",en:"Chinese culture is amazing. I'd like to learn more.",cn:"中国文化太棒了。我想多了解一些。"}]},{unitId:"g5bu4",scene:"A hero presentation",sceneCn:"英雄分享会",bigQuestion:"Who is your hero and why?",bigQuestionCn:"谁是心中的英雄？为什么？",tip:"说英雄时，用 because 说明他 / 她做了什么。",dialogue:[{speaker:"Miss Li",voice:"a",en:"Who is your hero, Ben?",cn:"本，你心中的英雄是谁？"},{speaker:"Ben",voice:"b",en:"My hero is my father. He is a firefighter.",cn:"我心中的英雄是爸爸，他是一名消防员。"},{speaker:"Miss Li",voice:"a",en:"Why do you admire him?",cn:"你为什么钦佩他？"},{speaker:"Ben",voice:"b",en:"He is brave. He protects people and never gives up.",cn:"他很勇敢，保护人们，从不放弃。"},{speaker:"Mia",voice:"a",en:"My hero is my grandma. She is hard-working and kind.",cn:"我心中的英雄是奶奶，她勤奋又善良。"}]},{unitId:"g5bu5",scene:"An environment club",sceneCn:"环保社团",bigQuestion:"How can we protect the earth?",bigQuestionCn:"我们能怎样保护地球？",tip:"说环保行动用 We can + 动作 + to protect ...",dialogue:[{speaker:"Amy",voice:"a",en:"Let's join the environment club.",cn:"我们加入环保社团吧。"},{speaker:"Ben",voice:"b",en:"Good idea. We can recycle paper and bottles.",cn:"好主意。我们可以回收纸张和瓶子。"},{speaker:"Amy",voice:"a",en:"We should save water and energy too.",cn:"我们还应该节约水和能源。"},{speaker:"Ben",voice:"b",en:"I will bring my own bag and not use plastic bags.",cn:"我会自带袋子，不用塑料袋。"},{speaker:"Amy",voice:"a",en:"Great! Let's plant a tree this weekend.",cn:"太好了！这个周末我们种一棵树吧。"}]},{unitId:"g5bu6",scene:"The last class",sceneCn:"最后一节课",bigQuestion:"How do we say goodbye to primary school?",bigQuestionCn:"怎样和小学说再见？",tip:"用 Thank you for ... 表达感谢，用 I will never forget ... 表达回忆。",dialogue:[{speaker:"Miss Li",voice:"a",en:"This is our last class. What will you remember?",cn:"这是我们的最后一节课。你们会记得什么？"},{speaker:"Ben",voice:"b",en:"I will never forget our football games.",cn:"我永远不会忘记我们的足球赛。"},{speaker:"Mia",voice:"a",en:"Thank you for teaching us, Miss Li.",cn:"谢谢您教我们，李老师。"},{speaker:"Miss Li",voice:"b",en:"Thank you too. I hope you follow your dreams.",cn:"也谢谢你们。希望你们追随自己的梦想。"},{speaker:"Ben",voice:"a",en:"Let's keep in touch and be friends forever!",cn:"我们保持联系，永远做朋友！"}]},{unitId:"g6au1",scene:"A class meeting",sceneCn:"主题班会",bigQuestion:"What does growing up mean to you?",bigQuestionCn:"长大对你来说意味着什么？",tip:"说成长时可以用 I am growing up，再用 I am proud of ... 表达感受。",dialogue:[{speaker:"Amy",voice:"a",en:"What does growing up mean to you, Ben?",cn:"本，长大对你来说意味着什么？"},{speaker:"Ben",voice:"b",en:"I think it means I can do more things by myself.",cn:"我觉得意味着我能自己做更多事。"},{speaker:"Amy",voice:"a",en:"Yes. I am more confident than before.",cn:"是的，我比以前更自信了。"},{speaker:"Ben",voice:"b",en:"And we should be careful and take responsibility.",cn:"我们还应该细心，承担责任。"},{speaker:"Amy",voice:"a",en:"I am proud of our progress this year.",cn:"我为我们今年的进步感到自豪。"}]},{unitId:"g6au2",scene:"On a city tour",sceneCn:"城市游览",bigQuestion:"What is Guangzhou famous for?",bigQuestionCn:"广州以什么闻名？",tip:"介绍城市可以用 ... is famous for ...。",dialogue:[{speaker:"Lily",voice:"a",en:"Welcome to Guangzhou! Is this your first visit?",cn:"欢迎来广州！这是你第一次来吗？"},{speaker:"Tom",voice:"b",en:"Yes. What is Guangzhou famous for?",cn:"是的。广州以什么闻名？"},{speaker:"Lily",voice:"a",en:"It is famous for dim sum and the Canton Tower.",cn:"它以点心和广州塔闻名。"},{speaker:"Tom",voice:"b",en:"Can we take the metro to the Pearl River?",cn:"我们可以坐地铁去珠江吗？"},{speaker:"Lily",voice:"a",en:"Sure. In spring, we can also visit the flower market.",cn:"当然。春天我们还可以去逛花市。"}]},{unitId:"g6au3",scene:"An international class",sceneCn:"国际课堂",bigQuestion:"How can we learn about the world?",bigQuestionCn:"我们怎样了解世界？",tip:"问对方来自哪里用 Where are you from?",dialogue:[{speaker:"Amy",voice:"a",en:"Where are you from, Ken?",cn:"肯，你来自哪里？"},{speaker:"Ken",voice:"b",en:"I am from Australia. My country is far away.",cn:"我来自澳大利亚，我的国家很远。"},{speaker:"Amy",voice:"a",en:"What language do people speak there?",cn:"那里的人说什么语言？"},{speaker:"Ken",voice:"b",en:"We speak English. But I am learning Chinese too.",cn:"我们说英语，不过我也在学中文。"},{speaker:"Amy",voice:"a",en:"Great! We can communicate and share our culture.",cn:"太好了！我们可以交流，分享各自的文化。"}]},{unitId:"g6au4",scene:"At the science museum",sceneCn:"科技馆",bigQuestion:"How does technology help us?",bigQuestionCn:"科技怎样帮助我们？",tip:"说用途可以用 I use ... to ...。",dialogue:[{speaker:"Ben",voice:"a",en:"Look at this robot! It can answer questions.",cn:"看这个机器人！它会回答问题。"},{speaker:"Amy",voice:"b",en:"Technology is amazing. I use the internet to find information.",cn:"科技真神奇。我用互联网查找信息。"},{speaker:"Ben",voice:"a",en:"I learn to write code on the computer.",cn:"我在电脑上学习写代码。"},{speaker:"Amy",voice:"b",en:"But we should not look at the screen for too long.",cn:"但是我们不应该长时间看屏幕。"},{speaker:"Ben",voice:"a",en:"Right. Technology is useful when we use it well.",cn:"对。用得好，科技才有用。"}]},{unitId:"g6au5",scene:"A class project",sceneCn:"班级环保项目",bigQuestion:"What can we do to protect the earth?",bigQuestionCn:"我们能做什么来保护地球？",tip:"提建议可以用 We should ... 和 Let's ...。",dialogue:[{speaker:"Tom",voice:"a",en:"Our class project is about the environment.",cn:"我们的班级项目是关于环境的。"},{speaker:"Lily",voice:"b",en:"We should recycle paper and bottles.",cn:"我们应该回收纸和瓶子。"},{speaker:"Tom",voice:"a",en:"We can also save energy by turning off the lights.",cn:"我们还可以随手关灯来节约能源。"},{speaker:"Lily",voice:"b",en:"Plastic waste causes pollution in the sea.",cn:"塑料废弃物会造成海洋污染。"},{speaker:"Tom",voice:"a",en:"Let's protect our planet together.",cn:"让我们一起保护我们的星球吧。"}]},{unitId:"g6au6",scene:"Talking about festivals",sceneCn:"聊节日",bigQuestion:"Which festival do you like best?",bigQuestionCn:"你最喜欢哪个节日？",tip:"介绍节日可以用 We celebrate ... by ...。",dialogue:[{speaker:"Amy",voice:"a",en:"Which festival do you like best, Ben?",cn:"本，你最喜欢哪个节日？"},{speaker:"Ben",voice:"b",en:"I like the Spring Festival. My family gather and celebrate together.",cn:"我喜欢春节。一家人聚在一起庆祝。"},{speaker:"Amy",voice:"a",en:"We also eat mooncakes at the Mid-Autumn Festival.",cn:"我们在中秋节也会吃月饼。"},{speaker:"Ben",voice:"b",en:"I love the lanterns. What is your favourite tradition?",cn:"我喜欢灯笼。你最喜欢的传统是什么？"},{speaker:"Amy",voice:"a",en:"We make dumplings and wish each other good luck.",cn:"我们包饺子，互祝好运。"}]},{unitId:"g6bu1",scene:"The first week of term",sceneCn:"开学第一周",bigQuestion:"What is your school life like?",bigQuestionCn:"你的校园生活是什么样的？",tip:"介绍课程用 My favourite subject is ...。",dialogue:[{speaker:"Ben",voice:"a",en:"We have a new timetable this term.",cn:"这学期我们有新的课程表。"},{speaker:"Amy",voice:"b",en:"Yes, we have four lessons in the morning.",cn:"是的，我们上午有四节课。"},{speaker:"Ben",voice:"a",en:"My favourite subject is science. We have an exam next week.",cn:"我最喜欢的科目是科学。我们下周有考试。"},{speaker:"Amy",voice:"b",en:"I joined the reading club. There is an activity every Friday.",cn:"我加入了阅读社团，每周五都有活动。"},{speaker:"Ben",voice:"a",en:"Good luck! Remember to finish your homework and practise every day.",cn:"祝你好运！记得每天完成作业、坚持练习。"}]},{unitId:"g6bu2",scene:"Planning the summer holiday",sceneCn:"规划暑假",bigQuestion:"What are you going to do this summer?",bigQuestionCn:"这个暑假你打算做什么？",tip:"说计划可以用 I'm going to ...，再用 First / Then 讲步骤。",dialogue:[{speaker:"Lily",voice:"a",en:"What are you going to do this summer, Tom?",cn:"汤姆，这个暑假你打算做什么？"},{speaker:"Tom",voice:"b",en:"I am going to read ten books. My goal is to improve my English.",cn:"我打算读十本书，目标是提高英语。"},{speaker:"Lily",voice:"a",en:"Good plan! How will you prepare?",cn:"好计划！你打算怎么准备？"},{speaker:"Tom",voice:"b",en:"First, I will choose the books. Then I will read for thirty minutes every day.",cn:"首先我会选书，然后每天读三十分钟。"},{speaker:"Lily",voice:"a",en:"I am sure you can achieve your goal.",cn:"我相信你一定能实现目标。"}]},{unitId:"g6bu3",scene:"At the zoo",sceneCn:"动物园",bigQuestion:"How can we protect wild animals?",bigQuestionCn:"我们怎样保护野生动物？",tip:"说动物住在哪里可以用 ... live in ...。",dialogue:[{speaker:"Amy",voice:"a",en:"Look at the giraffe! It has a very long neck.",cn:"看那只长颈鹿！它的脖子好长。"},{speaker:"Ben",voice:"b",en:"Dolphins are clever. They live in the sea.",cn:"海豚很聪明，它们生活在海里。"},{speaker:"Amy",voice:"a",en:"Penguins live in cold places, and camels can walk in the desert.",cn:"企鹅生活在寒冷的地方，骆驼能在沙漠中行走。"},{speaker:"Ben",voice:"b",en:"Many wild animals are in danger now.",cn:"现在很多野生动物都处于危险中。"},{speaker:"Amy",voice:"a",en:"We must protect their habitats and stop buying things made from them.",cn:"我们必须保护它们的栖息地，不再购买野生动物制品。"}]},{unitId:"g6bu4",scene:"At the book club",sceneCn:"读书会",bigQuestion:"What makes a story interesting?",bigQuestionCn:"什么让故事有趣？",tip:"复述故事可以用 The story is about ...。",dialogue:[{speaker:"Lily",voice:"a",en:"What are you reading, Ben?",cn:"本，你在读什么？"},{speaker:"Ben",voice:"b",en:"A legend about Nian. The main character is a brave boy.",cn:"一个关于年的传说。主要人物是一个勇敢的男孩。"},{speaker:"Lily",voice:"a",en:"I like stories with magic and adventure.",cn:"我喜欢有魔法和冒险的故事。"},{speaker:"Ben",voice:"b",en:"Me too. The ending was surprising, and the message was clear.",cn:"我也是。结局出人意料，寓意也很清楚。"},{speaker:"Lily",voice:"a",en:"Good stories always fire our imagination.",cn:"好故事总能激发我们的想象力。"}]},{unitId:"g6bu5",scene:"At the school clinic",sceneCn:"校医室",bigQuestion:"How can we stay healthy?",bigQuestionCn:"我们怎样保持健康？",tip:"谈健康可以用 It is important to ...。",dialogue:[{speaker:"Tom",voice:"a",en:"I feel tired these days, doctor.",cn:"医生，我最近觉得很累。"},{speaker:"Doctor",voice:"b",en:"Do you sleep well and exercise every day?",cn:"你每天睡得好、有锻炼吗？"},{speaker:"Tom",voice:"a",en:"Not really. I have too much homework and stress.",cn:"不太有。我作业太多，压力也大。"},{speaker:"Doctor",voice:"b",en:"You need a balance between study and rest. Eat a healthy diet and relax after class.",cn:"你需要在学习和休息之间取得平衡。注意健康饮食，课后放松一下。"},{speaker:"Tom",voice:"a",en:"I will try to sleep early and exercise every day.",cn:"我会尽量早睡，每天锻炼。"}]},{unitId:"g6bu6",scene:"A dream-sharing class",sceneCn:"梦想分享课",bigQuestion:"What do you want to be in the future?",bigQuestionCn:"你未来想成为什么？",tip:"说理想可以用 I want to be ...，再说明为什么。",dialogue:[{speaker:"Amy",voice:"a",en:"What do you want to be, Ben?",cn:"本，你未来想成为什么？"},{speaker:"Ben",voice:"b",en:"I want to be an astronaut and travel to space.",cn:"我想成为一名宇航员，去太空旅行。"},{speaker:"Amy",voice:"a",en:"That is cool! What about you, Lily?",cn:"太酷了！莉莉，你呢？"},{speaker:"Lily",voice:"b",en:"I want to be an artist. I draw every day.",cn:"我想成为一名艺术家，我每天都画画。"},{speaker:"Ben",voice:"a",en:"I believe that hard work will make our dreams come true.",cn:"我相信努力会让我们的梦想实现。"}]}],c={version:l,lessons:u},d=1,p=[{unitId:"s3u1",title:"Letters All Around",titleCn:"身边的字母",warmup:"Where can you see letters in your life?",warmupCn:"生活中，你在哪里能看到字母？",en:"Hello! I’m Ben. I’m a new student in Class Three. Letters are all around me. My name card says B-E-N. My ruler has numbers and letters. My schoolbag has a big “S” on it. At school, I meet my teacher, Mr Chen. He says, “Hi, Ben! Nice to meet you.” Letters help me read, write and meet new friends. I like letters!",cn:"你好！我是本，三年级的新学生。字母就在我身边。我的名字卡上写着 B-E-N。我的尺子上有数字和字母。我的书包上有一个大大的“S”。在学校，我遇到陈老师。他说：“嗨，本！很高兴认识你。”字母帮助我阅读、书写，也帮助我认识新朋友。我喜欢字母！",quiz:[{q:"Who is Ben?",options:["A teacher","A new student","A driver"],answer:1,explain:"短文开头说 Ben 是三年级的新学生。"},{q:"Where does Ben see a big “S”?",options:["On his schoolbag","On his ruler","On his name card"],answer:0,explain:"他的书包上有一个大大的“S”。"},{q:"What do letters help Ben do?",options:["Swim and jump","Cook and clean","Read, write and meet friends"],answer:2,explain:"短文最后说字母帮助他阅读、书写和认识新朋友。"}]},{unitId:"s3u2",title:"Food Words",titleCn:"食物词大集合",warmup:"What food words do you know in English?",warmupCn:"你会用英语说哪些食物？",en:"It’s lunch time. Mia and Ben look at the food table. “What’s this?” asks Mia. “It’s a hamburger,” says Ben. “I know! It’s from England.” “Can you guess this one?” asks Mia. “It’s a cookie. And this is chocolate.” Ben laughs. “Look, salad and coffee! But a sofa is not food.” Mia says, “In Chinese, we say shā fā. In English, it’s sofa. English and Chinese are fun!”",cn:"午饭时间到了。米娅和本看着餐桌。“这是什么？”米娅问。“这是一个汉堡，”本说，“我知道！它来自英国。”“你能猜猜这个吗？”米娅问。“这是一块饼干。这是巧克力。”本笑了。“看，沙拉和咖啡！不过沙发可不是食物。”米娅说：“中文里我们说‘沙发’，英语里是 sofa。英语和汉语真有趣！”",quiz:[{q:"What does Mia ask first?",options:["What time is it?","What’s this?","Who’s this?"],answer:1,explain:"米娅最先问的是 What’s this?（这是什么？）"},{q:"Which one is NOT food?",options:["salad","coffee","sofa"],answer:2,explain:"sofa 是沙发，不是食物。"},{q:"What does Mia think is fun?",options:["English and Chinese","The food table","The hamburger"],answer:0,explain:"米娅最后说 English and Chinese are fun!"}]},{unitId:"s3u3",title:"A New Friend",titleCn:"新朋友",warmup:"How do you introduce yourself?",warmupCn:"你会怎样介绍自己？",en:"It is Monday morning. A new girl stands at the school gate. “Good morning!” says Mr Chen. “What’s your name?” “Good morning, Mr Chen. My name is Amy,” she says. “This is Tom. He is a student, too,” says Mr Chen. Amy smiles. “Nice to meet you, Tom.” Tom gives her a card. “This is my name card. Welcome to our class!” Now Amy has a new friend.",cn:"星期一的早晨，一个女孩站在校门口。“早上好！”陈老师说，“你叫什么名字？”“早上好，陈老师。我叫艾米，”她说。“这是汤姆。他也是一名学生，”陈老师说。艾米笑了：“很高兴认识你，汤姆。”汤姆递给她一张卡片：“这是我的名字卡片。欢迎来到我们班！”现在，艾米有了一个新朋友。",quiz:[{q:"Who is the new girl?",options:["Amy","Mia","Ms Lin"],answer:0,explain:"新来的女孩说自己叫 Amy。"},{q:"What does Tom give Amy?",options:["A ruler","A name card","A cookie"],answer:1,explain:"Tom 给 Amy 一张名字卡片。"},{q:"When does the story happen?",options:["Friday afternoon","Monday morning","Sunday evening"],answer:1,explain:"故事发生在星期一的早晨。"}]},{unitId:"s3u4",title:"A Rainbow Keyboard",titleCn:"彩虹键盘",warmup:"What colours can you see on a keyboard?",warmupCn:"键盘上能看到哪些颜色？",en:"Ms Lin gives every student a keyboard picture. “Look at the keyboard. What colour is it?” she asks. “It’s white!” says Leo. “Now colour the keys,” says Ms Lin. Leo colours one key red, two keys yellow and three keys green. “How do you spell green?” asks Leo. “G-R-E-E-N,” says Ms Lin. Leo has a blue pencil, too. Soon the keyboard is red, yellow, green and blue. “My keyboard is a rainbow!” says Leo.",cn:"林老师给每位学生一张键盘图。“看这个键盘，它是什么颜色的？”她问。“是白色的！”利奥说。“现在给按键涂色吧，”林老师说。利奥把一个按键涂成红色，两个涂成黄色，三个涂成绿色。“green 怎么拼写？”利奥问。“G-R-E-E-N，”林老师说。利奥还有一支蓝色的铅笔。很快，键盘变成了红、黄、绿、蓝。“我的键盘是一道彩虹！”利奥说。",quiz:[{q:"What colour is the keyboard at first?",options:["Red","White","Blue"],answer:1,explain:"利奥一开始说键盘是白色的。"},{q:"How many keys does Leo colour green?",options:["Three","Two","Four"],answer:0,explain:"利奥把三个按键涂成绿色。"},{q:"How does Ms Lin spell green?",options:["G-R-E-N","G-R-E-E-N","G-R-E-E"],answer:1,explain:"林老师读出的拼写是 G-R-E-E-N。"}]},{unitId:"s3u5",title:"Our Class Tablet",titleCn:"班级平板",warmup:"Why do we need a password?",warmupCn:"我们为什么需要密码？",en:"Our class has a new tablet. Mr Chen says, “Let’s set a password.” He chooses four letters and four numbers: M-I-A-S and 3-5-7-9. Mia says, “Can you say that again?” Mr Chen says, “Sure. Put them in order: M-I-A-S, three, five, seven, nine.” Mia types the password. The tablet opens! “Now our class work is safe,” says Mr Chen. Mia writes the password in her notebook, but she covers it with a card.",cn:"我们班有了一台新平板。陈老师说：“我们来设置一个密码吧。”他选了四个字母和四个数字：M-I-A-S 和 3-5-7-9。米娅说：“你能再说一遍吗？”陈老师说：“当然。把它们按顺序排好：M-I-A-S，三、五、七、九。”米娅输入密码，平板打开了！“现在我们班的作业安全了，”陈老师说。米娅把密码写进笔记本，但她用一张卡片把它盖住了。",quiz:[{q:"How many letters are in the password?",options:["Three","Four","Five"],answer:1,explain:"密码里有 M、I、A、S 四个字母。"},{q:"Which number is NOT in the password?",options:["Six","Three","Nine"],answer:0,explain:"密码中的数字是 3、5、7、9，没有 6。"},{q:"What does Mia do with the password?",options:["She writes it on the board","She writes it in her notebook and covers it","She tells the whole school"],answer:1,explain:"米娅把密码写进笔记本，并用卡片盖住。"}]},{unitId:"s3u6",title:"Draw a Happy Face",titleCn:"画一张笑脸",warmup:"What do you need to draw a face?",warmupCn:"画一张脸需要画哪些部位？",en:"It is Art class. Lily draws a face on a big paper. First, she draws a round head. Then she draws two eyes, a nose and a mouth. “What colour is the hair?” asks Ms Lin. “It’s black,” says Lily. She draws two ears, too. “Look! These are the ears. This is the face,” says Lily. “Can you draw a body?” asks Ms Lin. “Yes, I can!” says Lily. Soon a happy boy is on the paper. Lily writes her name under the picture.",cn:"美术课上，莉莉在一张大纸上画脸。她先画了一个圆圆的头，然后画了两只眼睛、一个鼻子和一张嘴。“头发是什么颜色的？”林老师问。“黑色的，”莉莉说。她还画了两只耳朵。“看！这些是耳朵。这是脸，”莉莉说。“你会画身体吗？”林老师问。“会的！”莉莉说。很快，纸上出现了一个快乐的男孩。莉莉在画下面写上了自己的名字。",quiz:[{q:"What does Lily draw first?",options:["Two eyes","A round head","A mouth"],answer:1,explain:"莉莉先画了一个圆圆的头。"},{q:"What colour is the hair?",options:["Black","White","Red"],answer:0,explain:"莉莉说头发是黑色的。"},{q:"Who asks Lily to draw a body?",options:["Mr Chen","Her mother","Ms Lin"],answer:2,explain:"林老师问她会不会画身体。"}]},{unitId:"s3u7",title:"Listening with Heart",titleCn:"用心倾听",warmup:"What makes a good listener?",warmupCn:"怎样才算是好的倾听者？",en:"Mr Chen is giving a lesson. He says, “Listen carefully, please.” Ben sits quietly. He looks at the teacher and nods. “I have a question,” says Ben. “I don’t understand this word.” “I see,” says Mr Chen. “Follow me: lis-ten, listen.” Ben listens with his ears, his eyes and his heart. Soon he can read the word. Mr Chen smiles. “Good listeners are good learners.” Ben is happy. He is a good listener and a good friend.",cn:"陈老师正在上课。他说：“请仔细听。”本安静地坐着。他看着老师，点点头。“我有一个问题，”本说，“我不明白这个单词。”陈老师说：“我明白了。跟我读：lis-ten，listen。”本用耳朵、眼睛和心去听。很快，他能读这个单词了。陈老师笑了：“好的倾听者也是好的学习者。”本很开心。他是一个好听众，也是一个好朋友。",quiz:[{q:"What does Ben do when he listens?",options:["He runs around","He looks at the teacher and nods","He talks to a friend"],answer:1,explain:"本看着老师并点头。"},{q:"What is Ben’s question about?",options:["A word","The time","Lunch"],answer:0,explain:"本说他不明白这个单词。"},{q:"What does Mr Chen say about good listeners?",options:["They are very tall","They are good learners","They are quiet all day"],answer:1,explain:"陈老师说好的倾听者也是好的学习者。"}]},{unitId:"s3u8",title:"The Animal Game",titleCn:"动物模仿游戏",warmup:"Which animal can you move like?",warmupCn:"你能模仿哪种动物？",en:"It is PE time. Mr Zhou says, “Let’s play an animal game. Are you ready?” “Yes!” says the class. “Jump like a monkey!” says Mr Zhou. The children jump high. “Swim like a fish!” They move their arms and swim in the air. “Move like a bird! Fly!” says Mr Zhou. The children run and fly like birds. Then they roar like a tiger and walk like a bear. “I can move like a horse, too!” says Ben. Everyone laughs. What a fun PE class!",cn:"体育课时间到了。周老师说：“我们来玩动物游戏。准备好了吗？”“准备好了！”全班回答。“像猴子一样跳！”周老师说。孩子们高高跳起。“像鱼一样游！”他们摆动手臂，在空中游了起来。“像鸟一样移动！飞吧！”周老师说。孩子们像鸟一样跑着飞。接着他们像老虎一样吼叫，像熊一样走路。“我还能像马一样跑！”本说。大家都笑了。这真是一节有趣的体育课！",quiz:[{q:"What game does the class play?",options:["A ball game","An animal game","A word game"],answer:1,explain:"周老师带大家玩动物游戏。"},{q:"What does the class do like a fish?",options:["Swim","Jump","Roar"],answer:0,explain:"孩子们像鱼一样游。"},{q:"Which animal is NOT in the story?",options:["An elephant","A tiger","A bear"],answer:0,explain:"故事里没有出现大象。"}]},{unitId:"x3u1",title:"Mia’s Morning",titleCn:"米娅的早晨",warmup:"What do you do first in the morning?",warmupCn:"早晨起床后你先做什么？",en:"My name is Mia. I get up at seven o’clock. First, I get dressed. Then I brush my teeth and wash my face. After that, I comb my hair. My mum calls, “Breakfast is ready!” We have breakfast together. I have milk and eggs. “Don’t forget to pack your schoolbag,” says Mum. I put my books and my ruler in my bag. At seven forty, I say, “Goodbye, Mum!” and go to school. I am ready for a new day.",cn:"我叫米娅。我七点起床。先穿好衣服，然后刷牙、洗脸。之后我梳头。妈妈喊：“早餐好啦！”我们一起吃早餐。我喝牛奶、吃鸡蛋。“别忘了收拾书包，”妈妈说。我把书和尺子放进书包。七点四十，我说：“再见，妈妈！”然后去上学。我准备好迎接新的一天了。",quiz:[{q:"What does Mia do after she gets dressed?",options:["She brushes her teeth","She has breakfast","She reads a book"],answer:0,explain:"米娅穿好衣服后刷牙、洗脸。"},{q:"What does Mia have for breakfast?",options:["Rice and fish","Milk and eggs","Bread and coffee"],answer:1,explain:"米娅早餐喝牛奶、吃鸡蛋。"},{q:"What does Mum tell Mia not to forget?",options:["Her name card","Packing her schoolbag","Washing her face"],answer:1,explain:"妈妈提醒她别忘了收拾书包。"}]},{unitId:"x3u2",title:"Ten Thirty!",titleCn:"十点半啦！",warmup:"What time do you go to school?",warmupCn:"你几点去上学？",en:"Ben wakes up late. He asks, “Mum, what time is it?” “It’s ten thirty!” says Mum. “Oh no!” says Ben. “It’s time to have class. I’m late!” He gets dressed in a hurry. At ten forty, Ben and his sister go to school. They run all the way. At the school gate, Mia says, “Hurry up, Ben!” The teacher is in the classroom. Ben says, “I’m sorry I’m late.” Tomorrow he will get up early.",cn:"本起晚了。他问：“妈妈，几点了？”“十点半了！”妈妈说。“糟糕！”本说，“该上课了。我迟到了！”他匆匆穿好衣服。十点四十，本和妹妹去上学。他们一路跑着。在校门口，米娅说：“快点，本！”老师已经在教室里了。本说：“对不起，我迟到了。”明天他要早点起床。",quiz:[{q:"What time is it when Ben wakes up?",options:["Ten thirty","Seven o’clock","Nine thirty"],answer:0,explain:"妈妈说十点半了。"},{q:"What does Ben do in a hurry?",options:["He has breakfast","He gets dressed","He watches TV"],answer:1,explain:"本匆匆忙忙地穿好衣服。"},{q:"What will Ben do tomorrow?",options:["Go home early","Get up early","Sleep in class"],answer:1,explain:"短文最后说本明天要早点起床。"}]},{unitId:"x3u3",title:"Sam’s Day Plan",titleCn:"山姆的一天计划",warmup:"What do you do after school?",warmupCn:"放学后你会做什么？",en:"Hello, I’m Sam. I have lunch at twelve. Then I go to a school club from one to two. At four, I play sports for half an hour. After that, I go home. I have dinner at six with my family. Then I read books from seven to seven thirty. Sometimes I watch TV with my sister. At eight thirty, I pack my schoolbag. I check my books and my homework. A good plan makes a happy day!",cn:"你好，我是山姆。我十二点吃午饭，然后从一点到两点参加学校社团。四点，我做半小时运动。之后我回家。六点和家人吃晚饭。然后从七点到七点半看书。有时我和妹妹一起看电视。八点半，我收拾书包，检查书本和作业。好的计划让一天更快乐！",quiz:[{q:"When does Sam have lunch?",options:["At one","At twelve","At six"],answer:1,explain:"山姆十二点吃午饭。"},{q:"How long does Sam play sports?",options:["Half an hour","One hour","Two hours"],answer:0,explain:"山姆做半小时运动。"},{q:"What does Sam do before he goes to bed?",options:["He watches TV","He packs his schoolbag","He plays sports"],answer:1,explain:"山姆睡前收拾书包、检查作业。"}]},{unitId:"x3u4",title:"Join the Game",titleCn:"加入游戏",warmup:"How do you ask to join a game?",warmupCn:"你会怎样请求加入游戏？",en:"At break time, Lily and Tom are playing a ball game. Mia walks over. “Do you want to join us?” asks Lily. “I’d love to!” says Mia. “Can I have a turn?” “Sure,” says Tom. “You’re next after me. First, stand here and wait for the ball.” Mia tries to catch the ball. At first, she misses. Then she catches it! “Great!” says Lily. “You are good at this!” “It’s fun!” says Mia. “Can I play again?” “Of course!”",cn:"课间休息时，莉莉和汤姆在玩球。米娅走了过来。“你想加入我们吗？”莉莉问。“我很想！”米娅说，“能轮到我吗？”“当然，”汤姆说，“你在我之后。先站在这里等球。”米娅试着接球。一开始她没接到，后来她接住了！“太棒了！”莉莉说，“你很擅长这个！”“真好玩！”米娅说，“我可以再玩一次吗？”“当然可以！”",quiz:[{q:"Who asks Mia to join the game?",options:["Lily","Tom","Ben"],answer:0,explain:"莉莉问米娅要不要加入。"},{q:"What does Mia do first?",options:["She catches the ball","She runs home","She stands and waits"],answer:2,explain:"汤姆让米娅先站在那儿等球。"},{q:"What does Mia catch?",options:["A bird","A cookie","A ball"],answer:2,explain:"米娅最后接住了球。"}]},{unitId:"x3u5",title:"Our Class Poster",titleCn:"我们的班级海报",warmup:"What rules make a happy classroom?",warmupCn:"哪些约定能让教室更友好？",en:"Today, Class Three makes a poster. The poster says, “Our Classroom, Our Call.” Mia asks, “What are the rules in our class?” The students think. Ben says, “We should listen carefully.” Amy says, “We should take turns to speak.” Tom says, “We should put away our things.” Lily draws a hand and says, “We should give a helping hand.” The teacher smiles. “And don’t forget to do your best,” she says. The poster is bright and beautiful. Everyone signs their name.",cn:"今天，三班一起做海报。海报上写着：“我们的教室，我们的约定。”米娅问：“我们班有哪些规则？”同学们思考起来。本说：“我们应该仔细听。”艾米说：“我们应该轮流发言。”汤姆说：“我们应该收拾好自己的东西。”莉莉画了一只手，说：“我们应该伸出援手。”老师笑了：“别忘了尽最大努力。”海报明亮又漂亮，每个人都在上面签了名。",quiz:[{q:"What does Ben say?",options:["We should run in class","We should listen carefully","We should draw a hand"],answer:1,explain:"本说要仔细听。"},{q:"Who draws a hand?",options:["Mia","Tom","Lily"],answer:2,explain:"莉莉画了一只手。"},{q:"What is the poster about?",options:["A birthday","Animals","Class rules"],answer:2,explain:"海报的内容是班级约定。"}]},{unitId:"x3u6",title:"Duty Day",titleCn:"值日日",warmup:"What job would you like on duty day?",warmupCn:"值日时你想担任什么岗位？",en:"It is duty day in Class Three. Mr Chen asks, “What do you want to be, Mia?” “I want to be a line leader,” says Mia. “I can lead the way to the music room.” “Good!” says Mr Chen. “What do you want to do, Ben?” “I want to be a lunch helper. I can hand out food at lunch time.” Amy wants to be a teacher helper. She can put away books after class. Every job is important. At the end of the day, Mr Chen says, “Thank you! You did a great job.”",cn:"今天是三班的值日日。陈老师问：“米娅，你想当什么？”“我想当列队小帮手，”米娅说，“我可以带大家去音乐教室。”“很好！”陈老师说，“本，你想做什么？”“我想当午饭小帮手。我可以在午饭时分发食物。”艾米想当老师小帮手，她可以在课后整理书本。每个岗位都很重要。一天结束时，陈老师说：“谢谢你们！你们做得很棒。”",quiz:[{q:"What does Mia want to be?",options:["A lunch helper","A teacher helper","A line leader"],answer:2,explain:"米娅想当列队小帮手。"},{q:"What does Ben do?",options:["He leads the way","He hands out food","He puts away books"],answer:1,explain:"本当午饭小帮手，负责分发食物。"},{q:"What does Mr Chen say at the end of the day?",options:["Good morning!","Thank you! You did a great job.","Let’s go home."],answer:1,explain:"陈老师感谢大家，夸他们做得很棒。"}]},{unitId:"x3u7",title:"Rules at School",titleCn:"校园规则",warmup:"What should you do in the hallway?",warmupCn:"在走廊里应该怎么做？",en:"It is Monday. Ms Huang writes on the blackboard: “School Rules”. “What should we do at school?” she asks. Leo says, “We should keep to the right in the hallway.” Amy says, “We should get in line in the library.” “And in the classroom?” asks Ms Huang. “We should keep our voice down,” says Nina. After Chinese and Maths, they have Art and PE. In PE, Leo runs fast and shouts. “Oh, sorry!” he says. “It’s okay,” says Ms Huang. “Please keep your voice down.”",cn:"星期一，黄老师在黑板上写下：“校园规则”。“在学校我们应该怎么做？”她问。利奥说：“在走廊里应该靠右走。”艾米说：“在图书馆应该排队。”“在教室里呢？”黄老师问。“我们应该小声说话，”妮娜说。语文和数学课后，他们上美术和体育课。体育课上，利奥跑得很快，还大声喊叫。“哦，对不起！”他说。“没关系，”黄老师说，“请小声一点。”",quiz:[{q:"Where should we keep to the right?",options:["In the classroom","In the hallway","In the library"],answer:1,explain:"利奥说在走廊里要靠右走。"},{q:"What does Nina say in the classroom?",options:["Run fast","Get in line","Keep our voice down"],answer:2,explain:"妮娜说在教室里要小声说话。"},{q:"What does Leo say after he shouts?",options:["I’m late","Oh, sorry","Thank you"],answer:1,explain:"利奥大声喊叫后说 Oh, sorry!"}]},{unitId:"x3u8",title:"A Polite Afternoon",titleCn:"礼貌的下午",warmup:"How do you ask for help politely?",warmupCn:"怎样礼貌地请别人帮忙？",en:"It is a hot afternoon. The fan is off and the window is closed. Ms Lin says, “Ben, can you help me, please?” “Sure,” says Ben. “What can I do?” “Please turn on the lights and the fan. Then close the window,” says Ms Lin. Ben does it. “Thank you,” says Ms Lin. “You are welcome,” says Ben. Then he sees a chair near the blackboard. “Excuse me, Ms Lin. Is this your chair?” “Yes, it is,” she says. “Thank you for your help.” Ben smiles. It is nice to be polite.",cn:"一个炎热的下午，风扇关着，窗户也关着。林老师说：“本，你能帮我一下吗？”“当然，”本说，“我能做什么？”“请打开灯和风扇，然后关上窗户，”林老师说。本照做了。“谢谢你，”林老师说。“不客气，”本说。然后他看到黑板旁边有一把椅子。“打扰一下，林老师。这是您的椅子吗？”“是的，”她说，“谢谢你的帮助。”本笑了。讲礼貌真好。",quiz:[{q:"Who asks Ben for help?",options:["Ms Huang","Mia","Ms Lin"],answer:2,explain:"林老师请本帮忙。"},{q:"What does Ben turn on?",options:["The piano","The fan and the lights","The window"],answer:1,explain:"本打开风扇和灯。"},{q:"What does Ben find near the blackboard?",options:["A piano","A fan","A chair"],answer:2,explain:"本在黑板旁边看到一把椅子。"}]},{unitId:"g1au1",title:"Hello, New Friend",titleCn:"你好，新朋友",warmup:"How do you say hello to a new friend?",warmupCn:"你会怎样和新朋友打招呼？",en:"Hello! I am Mia. I am six. This is Ben. He is six too. We are new friends. We say hello every morning.",cn:"你好！我是米娅，我六岁。这是本，他也六岁。我们是新朋友。每天早上我们都会互相问好。",quiz:[{q:"How old is Mia?",options:["Six","Seven","Eight"],answer:0,explain:"短文说 I am six，米娅六岁。"},{q:"Who is Ben?",options:["A new friend","A teacher","A cat"],answer:0,explain:"Ben 是米娅的新朋友。"},{q:"What do they say every morning?",options:["Goodbye","Hello","Good night"],answer:1,explain:"短文最后说他们每天早上互相问好。"}]},{unitId:"g1au2",title:"My Family Photo",titleCn:"我的全家福",warmup:"Who is in your family photo?",warmupCn:"你的全家福里有谁？",en:"This is my family photo. My father is tall. My mother is kind. My little brother is four. We are in the park. We are happy together.",cn:"这是我的全家福。我的爸爸很高。我的妈妈很亲切。我的弟弟四岁。我们在公园里，在一起很开心。",quiz:[{q:"Who is tall?",options:["My father","My mother","My brother"],answer:0,explain:"短文说 My father is tall。"},{q:"How old is the little brother?",options:["Four","Six","Ten"],answer:0,explain:"弟弟四岁。"},{q:"Where are they?",options:["In the park","At school","In the shop"],answer:0,explain:"短文说 They are in the park。"}]},{unitId:"g1au3",title:"A Colourful Morning",titleCn:"彩色的早晨",warmup:"What colours can you see in the morning?",warmupCn:"早晨你能看到哪些颜色？",en:"Good morning! The sky is blue. The sun is yellow. The tree is green. My cat is black and white. What a colourful morning!",cn:"早上好！天空是蓝色的，太阳是黄色的，树是绿色的。我的猫是黑白相间的。多么多彩的早晨！",quiz:[{q:"What colour is the sky?",options:["Blue","Green","Red"],answer:0,explain:"短文说 The sky is blue。"},{q:"What colour is the sun?",options:["Yellow","White","Black"],answer:0,explain:"太阳是黄色的。"},{q:"What colour is the cat?",options:["Black and white","Red and blue","Green"],answer:0,explain:"猫是黑白相间的。"}]},{unitId:"g1au4",title:"Six Little Ducks",titleCn:"六只小鸭",warmup:"Can you count from one to six?",warmupCn:"你能从一数到六吗？",en:"I have six little ducks. One, two, three, four, five, six. They are yellow. They can swim. They say quack, quack! I love my six little ducks.",cn:"我有六只小鸭。一、二、三、四、五、六。它们是黄色的，会游泳。它们嘎嘎叫！我爱我的六只小鸭。",quiz:[{q:"How many ducks are there?",options:["Six","Five","Four"],answer:0,explain:"短文开头说 six little ducks。"},{q:"What colour are the ducks?",options:["Yellow","Blue","Green"],answer:0,explain:"小鸭是黄色的。"},{q:"What can the ducks do?",options:["Swim","Draw","Sing a song"],answer:0,explain:"短文说 They can swim。"}]},{unitId:"g1au5",title:"My Little Zoo",titleCn:"我的小小动物园",warmup:"Which animal do you like best?",warmupCn:"你最喜欢哪种动物？",en:"I have a little zoo at home. The cat is white. The dog is brown. The bird can sing. The fish can swim. The rabbit can jump. I love my little zoo!",cn:"我家里有一个小小动物园。猫是白色的，狗是棕色的。鸟会唱歌，鱼会游泳，兔子会跳。我爱我的小小动物园！",quiz:[{q:"What colour is the cat?",options:["White","Brown","Black"],answer:0,explain:"短文说 The cat is white。"},{q:"What can the bird do?",options:["Sing","Swim","Jump"],answer:0,explain:"鸟会唱歌。"},{q:"Who can jump?",options:["The rabbit","The fish","The cat"],answer:0,explain:"短文说 The rabbit can jump。"}]},{unitId:"g1au6",title:"My Funny Face",titleCn:"我的滑稽脸",warmup:"What can you draw on a funny face?",warmupCn:"你能在一张滑稽的脸上画什么？",en:"I draw a funny face. It has two big eyes. It has one small nose. Its mouth is big. Its ears are long. My friend laughs. I laugh too.",cn:"我画了一张滑稽的脸。它有两只大眼睛、一个小鼻子、一张大嘴巴和长耳朵。我的朋友笑了，我也笑了。",quiz:[{q:"How many eyes does the face have?",options:["Two","One","Three"],answer:0,explain:"短文说 It has two big eyes。"},{q:"What is small?",options:["The nose","The mouth","The ears"],answer:0,explain:"鼻子是小的。"},{q:"Who laughs?",options:["My friend and I","Only the teacher","The cat"],answer:0,explain:"朋友和我都笑了。"}]},{unitId:"g1bu1",title:"My Toy Box",titleCn:"我的玩具箱",warmup:"What is in your toy box?",warmupCn:"你的玩具箱里有什么？",en:"My toy box is big. I have a red ball, a blue car and a brown bear. My sister has a doll and a kite. We play together after school.",cn:"我的玩具箱很大。我有一个红球、一辆蓝车和一只棕熊。我的妹妹有一个娃娃和一只风筝。放学后我们一起玩。",quiz:[{q:"What colour is the ball?",options:["Red","Blue","Brown"],answer:0,explain:"短文说 a red ball。"},{q:"Who has a kite?",options:["My sister","I","My brother"],answer:0,explain:"妹妹有一只风筝。"},{q:"When do they play together?",options:["After school","In the morning","At night"],answer:0,explain:"短文说 after school。"}]},{unitId:"g1bu2",title:"Breakfast Time",titleCn:"早餐时间",warmup:"What do you have for breakfast?",warmupCn:"你早餐吃什么？",en:"It is breakfast time. I have bread, an egg and milk. My brother likes bananas. We have rice and fish for lunch. Good food makes us strong.",cn:"早餐时间到了。我吃面包、一个鸡蛋，喝牛奶。我的兄弟喜欢香蕉。我们午饭吃米饭和鱼。好食物让我们强壮。",quiz:[{q:"What does the writer have for breakfast?",options:["Bread, an egg and milk","Rice and fish","Only bananas"],answer:0,explain:"短文说 I have bread, an egg and milk。"},{q:"What does the brother like?",options:["Bananas","Eggs","Bread"],answer:0,explain:"兄弟喜欢香蕉。"},{q:"What do they have for lunch?",options:["Rice and fish","Cake and milk","Bread and eggs"],answer:0,explain:"午饭吃米饭和鱼。"}]},{unitId:"g1bu3",title:"Our Classroom",titleCn:"我们的教室",warmup:"What is in your classroom?",warmupCn:"你的教室里有什么？",en:"Our classroom is big and clean. I have a book and a pen on my desk. My bag is under the chair. My ruler is in my bag. We all like our classroom.",cn:"我们的教室又大又干净。我的课桌上有书和笔。我的书包在椅子下面，尺子在书包里。我们都喜欢我们的教室。",quiz:[{q:"What is on the desk?",options:["A book and a pen","A bag and a chair","A ruler and a bag"],answer:0,explain:"短文说书和笔在课桌上。"},{q:"Where is the bag?",options:["Under the chair","On the desk","In the bag"],answer:0,explain:"书包在椅子下面。"},{q:"Where is the ruler?",options:["In the bag","On the desk","Under the chair"],answer:0,explain:"尺子在书包里。"}]},{unitId:"g1bu4",title:"A Rainy Day",titleCn:"雨天",warmup:"What do you do on a rainy day?",warmupCn:"下雨天你会做什么？",en:"Today is rainy. It is not hot. I have a coat. My friend has an umbrella. We jump in the rain. Then the sun comes out. What a nice day!",cn:"今天下雨，不热。我穿着外套，朋友带着雨伞。我们在雨里跳。后来太阳出来了。多好的一天！",quiz:[{q:"What is the weather like today?",options:["Rainy","Sunny","Snowy"],answer:0,explain:"短文开头说 Today is rainy。"},{q:"What does the friend have?",options:["An umbrella","A kite","A coat"],answer:0,explain:"朋友有一把雨伞。"},{q:"What happens at the end?",options:["The sun comes out","It snows","It is windy"],answer:0,explain:"最后太阳出来了。"}]},{unitId:"g1bu5",title:"In the Playground",titleCn:"在操场上",warmup:"What can you do in the playground?",warmupCn:"你会在操场上做什么？",en:"It is playtime. I can run and jump. Mia can sing and dance. Ben can swim. We can draw a big sun. We are happy in the playground.",cn:"活动时间到了。我会跑和跳。米娅会唱歌和跳舞。本会游泳。我们会画一个大太阳。我们在操场上很开心。",quiz:[{q:"What can Mia do?",options:["Sing and dance","Swim and run","Draw and jump"],answer:0,explain:"米娅会唱歌和跳舞。"},{q:"Who can swim?",options:["Ben","Mia","I"],answer:0,explain:"短文说 Ben can swim。"},{q:"What do they draw?",options:["A big sun","A cat","A kite"],answer:0,explain:"他们画了一个大太阳。"}]},{unitId:"g1bu6",title:"Mia's Birthday",titleCn:"米娅的生日",warmup:"What do you do at a birthday party?",warmupCn:"生日聚会上你会做什么？",en:"Today is Mia's birthday. She is seven. We have a big cake with seven candles. We sing a song. I give her a gift. She is happy. We are happy too.",cn:"今天是米娅的生日，她七岁。我们有一个插着七根蜡烛的大蛋糕。我们唱歌，我送给她一份礼物。她很开心，我们也很开心。",quiz:[{q:"How old is Mia?",options:["Seven","Six","Eight"],answer:0,explain:"米娅七岁。"},{q:"How many candles are on the cake?",options:["Seven","Five","Six"],answer:0,explain:"蛋糕上有七根蜡烛。"},{q:"What does the writer give Mia?",options:["A gift","A cat","A cake"],answer:0,explain:"作者送给米娅一份礼物。"}]},{unitId:"g2au1",title:"My Best Friend",titleCn:"我最好的朋友",warmup:"What is your best friend like?",warmupCn:"你最好的朋友是什么样的人？",en:"My best friend is Amy. She is tall and kind. She has long hair. She can draw beautiful pictures. We play together every day. I am happy with my friend.",cn:"我最好的朋友是艾米。她又高又友善，留着长头发，能画出漂亮的画。我们每天一起玩，和朋友在一起我很开心。",quiz:[{q:"Who is the best friend?",options:["Amy","Ben","Mia"],answer:0,explain:"短文说 My best friend is Amy。"},{q:"What can Amy do?",options:["Draw beautiful pictures","Swim fast","Play football"],answer:0,explain:"艾米会画漂亮的画。"},{q:"How does the writer feel?",options:["Happy","Sad","Angry"],answer:0,explain:"短文最后说 I am happy。"}]},{unitId:"g2au2",title:"Welcome to Our School",titleCn:"欢迎来到我们的学校",warmup:"What places are in your school?",warmupCn:"你的学校里有哪些地方？",en:"Welcome to our school! This is our class. Our teacher is Miss Li. We read in the library. We run on the playground. The school gate is big and green. We love our school.",cn:"欢迎来到我们的学校！这是我们的班级，我们的老师是李老师。我们在图书馆看书，在操场上跑步。学校的大门又大又绿。我们爱我们的学校。",quiz:[{q:"Who is the teacher?",options:["Miss Li","Miss Chen","Mr Li"],answer:0,explain:"短文说 Our teacher is Miss Li。"},{q:"Where do they read?",options:["In the library","On the playground","At the gate"],answer:0,explain:"他们在图书馆看书。"},{q:"What colour is the school gate?",options:["Green","Red","Blue"],answer:0,explain:"学校大门是绿色的。"}]},{unitId:"g2au3",title:"Ben's Day",titleCn:"本的一天",warmup:"What time do you get up?",warmupCn:"你几点起床？",en:"Ben gets up at seven. He has breakfast at seven thirty. In the morning, he reads English. In the afternoon, he plays football. In the evening, he does his homework. He sleeps at nine.",cn:"本七点起床，七点半吃早餐。早上他读英语，下午踢足球，晚上做作业，九点睡觉。",quiz:[{q:"When does Ben get up?",options:["At seven","At seven thirty","At nine"],answer:0,explain:"本七点起床。"},{q:"What does Ben do in the afternoon?",options:["Play football","Read English","Sleep"],answer:0,explain:"他下午踢足球。"},{q:"When does Ben sleep?",options:["At nine","At seven","At ten"],answer:0,explain:"他九点睡觉。"}]},{unitId:"g2au4",title:"The Fruit Shop",titleCn:"水果店",warmup:"What fruit can you see in a fruit shop?",warmupCn:"水果店里能看到哪些水果？",en:"The fruit shop is small but nice. It has oranges, pears, peaches and watermelons. The grapes are purple. The strawberries are red. Mum buys three peaches and a watermelon. I am happy.",cn:"水果店不大但很漂亮。店里有橙子、梨、桃子和西瓜。葡萄是紫色的，草莓是红色的。妈妈买了三个桃子和一个西瓜，我很开心。",quiz:[{q:"What colour are the grapes?",options:["Purple","Red","Yellow"],answer:0,explain:"短文说 The grapes are purple。"},{q:"What colour are the strawberries?",options:["Red","Purple","Green"],answer:0,explain:"草莓是红色的。"},{q:"What does Mum buy?",options:["Three peaches and a watermelon","Three pears and grapes","A big cake"],answer:0,explain:"妈妈买了三个桃子和一个西瓜。"}]},{unitId:"g2au5",title:"Getting Dressed",titleCn:"穿衣服",warmup:"What are you wearing today?",warmupCn:"你今天穿着什么？",en:"It is cold today. I put on my coat, my hat and my blue socks. My sister is wearing a red dress and new shoes. We are ready for the party. We look nice!",cn:"今天很冷。我穿上外套，戴上帽子，穿上蓝袜子。妹妹穿着红裙子和新鞋子。我们准备好去参加聚会了，看起来真不错！",quiz:[{q:"What is the weather like?",options:["Cold","Hot","Sunny"],answer:0,explain:"短文说 It is cold today。"},{q:"What colour are the socks?",options:["Blue","Red","White"],answer:0,explain:"袜子是蓝色的。"},{q:"What is the sister wearing?",options:["A red dress and new shoes","A coat and a hat","A white shirt"],answer:0,explain:"妹妹穿红裙子和新鞋子。"}]},{unitId:"g2au6",title:"A Day in the Park",titleCn:"公园里的一天",warmup:"What do you like doing in the park?",warmupCn:"你喜欢在公园里做什么？",en:"Today is sunny. My family goes to the park. There are tall trees and red flowers. There is a big lake. We see two boats on the water. We sit on the green grass and have a picnic. What a happy day!",cn:"今天天气晴朗，我们一家去公园。公园里有高大的树和红色的花，还有一个大湖。我们看见水上有两只小船。我们坐在绿草地上野餐，多开心的一天！",quiz:[{q:"What is the weather like?",options:["Sunny","Rainy","Windy"],answer:0,explain:"短文开头说 Today is sunny。"},{q:"How many boats do they see?",options:["Two","One","Three"],answer:0,explain:"他们看见两只小船。"},{q:"Where do they sit?",options:["On the green grass","On a boat","Under a car"],answer:0,explain:"他们坐在绿草地上。"}]},{unitId:"g2bu1",title:"Hurry, Ben!",titleCn:"快点，本！",warmup:"What time do you go to school?",warmupCn:"你几点去上学？",en:`Ben gets up at seven o'clock. He has breakfast at half past seven. School starts at eight. Today he is late. He runs to the school gate. His teacher says, "Please be early next time."`,cn:"本七点起床，七点半吃早餐，八点开始上课。今天他迟到了，跑到校门口。老师说：“下次请早点来。”",quiz:[{q:"When does Ben get up?",options:["At seven o'clock","At half past seven","At eight"],answer:0,explain:"本七点起床。"},{q:"When does school start?",options:["At eight","At seven","At half past seven"],answer:0,explain:"短文说 School starts at eight。"},{q:"What does the teacher say?",options:["Please be early next time","Please run fast","Please go home"],answer:0,explain:"老师让他下次早点来。"}]},{unitId:"g2bu2",title:"Our Home",titleCn:"我们的家",warmup:"What is your favourite room at home?",warmupCn:"你最喜欢家里的哪个房间？",en:"Our home is not big, but it is warm. Dad cooks in the kitchen. Mum reads in the living room. I sleep in my bedroom. My sister washes her face in the bathroom. We love our home.",cn:"我们的家不大，但很温暖。爸爸在厨房做饭，妈妈在客厅看书，我在卧室睡觉，妹妹在浴室洗脸。我们爱我们的家。",quiz:[{q:"Where does Dad cook?",options:["In the kitchen","In the living room","In the bedroom"],answer:0,explain:"爸爸在厨房做饭。"},{q:"Where does Mum read?",options:["In the living room","In the bathroom","In the kitchen"],answer:0,explain:"妈妈在客厅看书。"},{q:"Where does the writer sleep?",options:["In the bedroom","In the living room","In the kitchen"],answer:0,explain:"作者在卧室睡觉。"}]},{unitId:"g2bu3",title:"Sports Day",titleCn:"运动会",warmup:"What sport do you like?",warmupCn:"你喜欢什么运动？",en:"Today is sports day. Ben plays football. Mia plays basketball. Amy runs in a race. Our team is strong. We win two games. We are tired but very happy.",cn:"今天是运动会。本踢足球，米娅打篮球，艾米参加赛跑。我们的队伍很强，赢了两场比赛。我们很累，但非常开心。",quiz:[{q:"What does Ben play?",options:["Football","Basketball","Tennis"],answer:0,explain:"本踢足球。"},{q:"Who runs in a race?",options:["Amy","Mia","Ben"],answer:0,explain:"艾米参加赛跑。"},{q:"How many games does the team win?",options:["Two","One","Three"],answer:0,explain:"他们赢了两场比赛。"}]},{unitId:"g2bu4",title:"People Who Help Us",titleCn:"帮助我们的人",warmup:"Who helps us in our life?",warmupCn:"生活中谁在帮助我们？",en:"Many people help us. The doctor and the nurse help sick people. The teacher teaches us at school. The driver drives the bus. The cook makes food. The farmer grows rice and vegetables. Thank you, everyone!",cn:"很多人都帮助我们。医生和护士帮助生病的人，老师在学校教我们，司机开公交车，厨师做食物，农民种水稻和蔬菜。谢谢每一个人！",quiz:[{q:"Who helps sick people?",options:["The doctor and the nurse","The cook and the farmer","The driver"],answer:0,explain:"医生和护士帮助生病的人。"},{q:"Who grows rice?",options:["The farmer","The teacher","The driver"],answer:0,explain:"农民种水稻。"},{q:"Who makes food?",options:["The cook","The nurse","The teacher"],answer:0,explain:"厨师做食物。"}]},{unitId:"g2bu5",title:"Four Seasons",titleCn:"四季",warmup:"Which season do you like best?",warmupCn:"你最喜欢哪个季节？",en:"There are four seasons in a year. Spring is warm and green. Summer is hot. We swim in summer. Autumn is cool. The leaves are golden. Winter is cold. We wear coats and play in the snow. Every season is beautiful.",cn:"一年有四个季节。春天温暖、满眼绿色；夏天炎热，我们游泳；秋天凉爽，树叶金黄；冬天寒冷，我们穿外套、在雪里玩。每个季节都很美。",quiz:[{q:"How many seasons are there in a year?",options:["Four","Three","Five"],answer:0,explain:"一年有四个季节。"},{q:"What do they do in summer?",options:["Swim","Play in the snow","Pick apples"],answer:0,explain:"夏天他们游泳。"},{q:"What colour are the leaves in autumn?",options:["Golden","Green","White"],answer:0,explain:"秋天的树叶是金黄色的。"}]},{unitId:"g2bu6",title:"Festivals in China",titleCn:"中国的节日",warmup:"What festivals do you know in China?",warmupCn:"你知道中国的哪些节日？",en:"China has many festivals. At the Spring Festival, families have a big dinner. At the Dragon Boat Festival, we watch dragon boat races. At Mid-Autumn, we eat mooncakes and look at the moon. We celebrate with our family. Festivals are happy times.",cn:"中国有很多节日。春节时一家人吃年夜饭，端午节看龙舟比赛，中秋节吃月饼、赏月。我们和家人一起庆祝。节日是快乐的时光。",quiz:[{q:"What do families do at the Spring Festival?",options:["Have a big dinner","Eat mooncakes","Watch boat races"],answer:0,explain:"春节时家人吃年夜饭。"},{q:"What do we watch at the Dragon Boat Festival?",options:["Dragon boat races","A football game","A film"],answer:0,explain:"端午节看龙舟比赛。"},{q:"What do we eat at Mid-Autumn?",options:["Mooncakes","Dumplings","Cake"],answer:0,explain:"中秋节吃月饼。"}]},{unitId:"g4au1",title:"Our New Classroom",titleCn:"我们的新教室",warmup:"What can you see in a classroom?",warmupCn:"在教室里你能看到什么？",en:"This is our new classroom. There are two big windows and a white door. A computer is next to the door. There are many pictures on the wall. The floor is clean. We turn on the lights and start our lesson. We all like our new classroom.",cn:"这是我们的新教室。有两扇大窗户和一扇白色的门，门旁边有一台电脑，墙上有很多画。地板很干净。我们打开灯开始上课。我们都喜欢新教室。",quiz:[{q:"How many windows are there?",options:["Two","One","Three"],answer:0,explain:"短文说 There are two big windows。"},{q:"Where is the computer?",options:["Next to the door","On the wall","Under the floor"],answer:0,explain:"电脑在门旁边。"},{q:"What is on the wall?",options:["Many pictures","A computer","A door"],answer:0,explain:"墙上有很多画。"}]},{unitId:"g4au2",title:"The Lost Schoolbag",titleCn:"丢失的书包",warmup:"What do you have in your schoolbag?",warmupCn:"你的书包里有什么？",en:`Amy cannot find her schoolbag. She is worried. Ben looks under the desk. Mia looks behind the door. They find a blue bag with a storybook, a notebook and two candies. "Is this yours?" asks Ben. "Yes, it's mine! Thank you!" says Amy. She is happy again.`,cn:"艾米找不到书包，很着急。本在桌子下面找，米娅在门后面找。他们找到一个蓝色书包，里面有故事书、笔记本和两颗糖。“这是你的吗？”本问。“是的，谢谢！”艾米又开心起来。",quiz:[{q:"Who lost the schoolbag?",options:["Amy","Ben","Mia"],answer:0,explain:"艾米找不到书包。"},{q:"What is NOT in the bag?",options:["A key","A storybook","Two candies"],answer:0,explain:"包里有故事书、笔记本和糖果，没有钥匙。"},{q:"How does Amy feel at the end?",options:["Happy","Angry","Tired"],answer:0,explain:"找到书包后她开心起来。"}]},{unitId:"g4au3",title:"My Friend Jack",titleCn:"我的朋友杰克",warmup:"What is your friend good at?",warmupCn:"你擅长什么？你的朋友呢？",en:"Jack is my best friend. He is tall and strong. He has short black hair and wears glasses. He is quiet, but he is always friendly. He likes science and music. He is good at drawing, too. We often read books together after school.",cn:"杰克是我最好的朋友。他又高又强壮，留着黑色短发，戴着眼镜。他很安静，但总是很友好。他喜欢科学和音乐，也擅长画画。放学后我们经常一起看书。",quiz:[{q:"What does Jack look like?",options:["Tall and strong with glasses","Short and thin","Tall with long hair"],answer:0,explain:"杰克又高又强壮，戴眼镜。"},{q:"What does Jack like?",options:["Science and music","Football and art","Cooking"],answer:0,explain:"他喜欢科学和音乐。"},{q:"What do they often do after school?",options:["Read books","Play football","Go shopping"],answer:0,explain:"放学后他们经常一起看书。"}]},{unitId:"g4au4",title:"A Tidy Home",titleCn:"整洁的家",warmup:"Is your home tidy?",warmupCn:"你的家整洁吗？",en:"My home is small but tidy. The living room has a big sofa and a clock on the wall. The table is near the window. The fridge is in the kitchen. My bedroom is upstairs. My bed is soft and my books are on the desk. I love my home.",cn:"我的家不大但很整洁。客厅里有一张大沙发，墙上挂着钟，桌子在窗边，冰箱在厨房。我的卧室在楼上，床很软，书在书桌上。我爱我的家。",quiz:[{q:"Where is the clock?",options:["On the wall","In the fridge","On the bed"],answer:0,explain:"钟在墙上。"},{q:"Where is the bedroom?",options:["Upstairs","In the kitchen","Near the sofa"],answer:0,explain:"卧室在楼上。"},{q:"Where are the books?",options:["On the desk","On the sofa","In the fridge"],answer:0,explain:"书在书桌上。"}]},{unitId:"g4au5",title:"Dinner at Home",titleCn:"家里的晚餐",warmup:"What do you have for dinner?",warmupCn:"你晚饭吃什么？",en:"It is six o'clock. Dinner is ready. We have beef, chicken, noodles, soup and vegetables. I set the table with bowls and chopsticks. Dad is hungry. He would like some beef. Mum would like some soup. We eat and talk together. Dinner at home is warm.",cn:"六点了，晚饭准备好了。我们有牛肉、鸡肉、面条、汤和蔬菜。我把碗和筷子摆上桌。爸爸饿了，想吃牛肉；妈妈想喝汤。我们边吃边聊，家里的晚餐很温暖。",quiz:[{q:"What time is it?",options:["Six o'clock","Seven o'clock","Five o'clock"],answer:0,explain:"短文开头说 It is six o'clock。"},{q:"What would Dad like?",options:["Some beef","Some soup","Some noodles"],answer:0,explain:"爸爸想要牛肉。"},{q:"What does the writer set on the table?",options:["Bowls and chopsticks","Plates and forks","Cups and spoons"],answer:0,explain:"作者摆上碗和筷子。"}]},{unitId:"g4au6",title:"Dream Jobs",titleCn:"梦想的职业",warmup:"What job do you want to do in the future?",warmupCn:"你未来想做什么工作？",en:"Everyone has a dream job. Ben wants to be a football player because he loves sports. Mia wants to be a doctor because she wants to help sick people. Amy wants to be a teacher. Their parents work hard every day. Every job is important. What is your dream job?",cn:"每个人都有自己的梦想职业。本想当足球运动员，因为他热爱运动；米娅想当医生，因为她想帮助病人；艾米想当老师。他们的父母每天努力工作。每份工作都很重要。你的梦想职业是什么？",quiz:[{q:"Why does Ben want to be a football player?",options:["Because he loves sports","Because he likes food","Because he is tall"],answer:0,explain:"本热爱运动。"},{q:"What does Mia want to be?",options:["A doctor","A teacher","A player"],answer:0,explain:"米娅想当医生。"},{q:"What does the text say about every job?",options:["It is important","It is easy","It is boring"],answer:0,explain:"短文说每份工作都很重要。"}]},{unitId:"g4bu1",title:"School Tour",titleCn:"校园参观",warmup:"Which place in your school do you like best?",warmupCn:"你最喜欢学校的哪个地方？",en:"Welcome to our school. The office is on the first floor. Our classroom is on the second floor. The library is next to the music room. We read and borrow books there. The art room is on the first floor. The gym is behind the playground. We love our school.",cn:"欢迎来到我们学校。办公室在一楼，我们的教室在二楼。图书馆在音乐室旁边，我们在那里看书、借书。美术室在一楼，体育馆在操场后面。我们爱我们的学校。",quiz:[{q:"Where is the office?",options:["On the first floor","On the second floor","Behind the gym"],answer:0,explain:"办公室在一楼。"},{q:"What is next to the music room?",options:["The library","The gym","The playground"],answer:0,explain:"图书馆在音乐室旁边。"},{q:"Where is the gym?",options:["Behind the playground","On the second floor","Next to the office"],answer:0,explain:"体育馆在操场后面。"}]},{unitId:"g4bu2",title:"A Busy Tuesday",titleCn:"忙碌的星期二",warmup:"What classes do you have on Tuesday?",warmupCn:"你星期二有什么课？",en:"Mia gets up at six forty on Tuesday. She has breakfast at seven. English class is at eight thirty. She has lunch at twelve. In the afternoon, she has music class and PE class. She goes home at five. She goes to bed at nine thirty. Tuesday is a busy day.",cn:"米娅星期二六点四十起床，七点吃早餐。英语课八点半开始，十二点吃午餐。下午她上音乐课和体育课，五点回家，九点半睡觉。星期二很忙。",quiz:[{q:"When does Mia get up?",options:["At six forty","At seven","At eight thirty"],answer:0,explain:"她六点四十起床。"},{q:"When is English class?",options:["At eight thirty","At twelve","At two"],answer:0,explain:"英语课八点半。"},{q:"What classes does she have in the afternoon?",options:["Music and PE","English and music","Art and maths"],answer:0,explain:"下午上音乐课和体育课。"}]},{unitId:"g4bu3",title:"Weather Report",titleCn:"天气预报",warmup:"What is the weather like today?",warmupCn:"今天天气怎么样？",en:"Good morning. Here is the weather report. In Guangzhou, it is cloudy in the morning. The temperature is twenty degrees. In the afternoon, it will rain. Please take an umbrella or a raincoat. Tomorrow will be sunny and warm. Have a nice day!",cn:"早上好，这里是天气预报。广州上午多云，气温二十度。下午会下雨，请带雨伞或雨衣。明天晴朗温暖。祝你今天愉快！",quiz:[{q:"What is the weather like in the morning?",options:["Cloudy","Sunny","Snowy"],answer:0,explain:"上午多云。"},{q:"What is the temperature?",options:["Twenty degrees","Twenty-five degrees","Ten degrees"],answer:0,explain:"气温二十度。"},{q:"What will the weather be like tomorrow?",options:["Sunny and warm","Rainy and cold","Cloudy and cool"],answer:0,explain:"明天晴朗温暖。"}]},{unitId:"g4bu4",title:"A Day on the Farm",titleCn:"农场的一天",warmup:"What animals live on a farm?",warmupCn:"农场里住着哪些动物？",en:"Today we visit Uncle Wang's farm. There are three horses, five cows and many sheep. The hens are under the tree. We pick red tomatoes, potatoes and carrots. The vegetables are fresh. We have lunch on the farm. It is a happy day.",cn:"今天我们参观王叔叔的农场。那里有三匹马、五头奶牛和许多绵羊，母鸡在树下。我们摘了红西红柿、土豆和胡萝卜，蔬菜很新鲜。我们在农场吃午饭，开心极了。",quiz:[{q:"How many cows are there?",options:["Five","Three","Many"],answer:0,explain:"有五头奶牛。"},{q:"Where are the hens?",options:["Under the tree","In the house","On the horse"],answer:0,explain:"母鸡在树下。"},{q:"What do they pick?",options:["Tomatoes, potatoes and carrots","Apples and pears","Flowers"],answer:0,explain:"他们摘西红柿、土豆和胡萝卜。"}]},{unitId:"g4bu5",title:"My Favourite Clothes",titleCn:"我最喜欢的衣服",warmup:"What clothes do you like wearing?",warmupCn:"你喜欢穿什么衣服？",en:"I have many clothes. My favourite is a blue jacket. It goes well with my white sweater. On hot days, I wear shorts and a T-shirt. On cold days, I wear a scarf and gloves. At school, I wear my uniform. Clothes keep us warm and happy.",cn:"我有很多衣服。我最喜欢一件蓝色夹克，它和我的白毛衣很搭。热天我穿短裤和 T 恤，冷天戴围巾和手套。在学校我穿校服。衣服让我们温暖又开心。",quiz:[{q:"What is the writer's favourite clothes?",options:["A blue jacket","A red skirt","White gloves"],answer:0,explain:"最喜欢的是蓝色夹克。"},{q:"What does the writer wear on hot days?",options:["Shorts and a T-shirt","A scarf and gloves","A jacket and sweater"],answer:0,explain:"热天穿短裤和 T 恤。"},{q:"What does the writer wear at school?",options:["A uniform","A jacket","Shorts"],answer:0,explain:"在学校穿校服。"}]},{unitId:"g4bu6",title:"Shopping with Mum",titleCn:"和妈妈购物",warmup:"What do you like to buy?",warmupCn:"你喜欢买什么？",en:"On Saturday, I go shopping with Mum. We go to a clothes shop. I find a blue jacket. It is fifty yuan. The price is good. I try it on. It fits me well. Mum buys it for me. I am very happy.",cn:"星期六我和妈妈去购物。我们走进一家服装店，我找到一件蓝色夹克，五十元，价格很合适。我试穿了一下，很合身，妈妈就买给了我。我非常开心。",quiz:[{q:"When do they go shopping?",options:["On Saturday","On Monday","On Sunday"],answer:0,explain:"短文说 On Saturday。"},{q:"How much is the jacket?",options:["Fifty yuan","Forty yuan","Fifteen yuan"],answer:0,explain:"夹克五十元。"},{q:"How does the jacket fit?",options:["Very well","Too big","Too small"],answer:0,explain:"试穿后很合身。"}]},{unitId:"g5au1",title:"My Hobbies",titleCn:"我的爱好",warmup:"What do you like doing after school?",warmupCn:"放学后你喜欢做什么？",en:"Everyone has hobbies. I like reading and painting. I spend an hour reading every day. My friend Amy likes singing and dancing. Ben likes collecting stamps. Hobbies make our free time interesting. They also help us make new friends.",cn:"每个人都有自己的爱好。我喜欢阅读和画画，每天花一小时读书。我的朋友艾米喜欢唱歌和跳舞，本喜欢收集邮票。爱好让我们的空闲时间更有趣，也帮我们交到新朋友。",quiz:[{q:"What does the writer like?",options:["Reading and painting","Singing and dancing","Collecting stamps"],answer:0,explain:"作者喜欢阅读和画画。"},{q:"How long does the writer read every day?",options:["An hour","Two hours","Ten minutes"],answer:0,explain:"作者每天读一小时。"},{q:"What do hobbies help us do?",options:["Make new friends","Sleep more","Eat more"],answer:0,explain:"爱好帮我们交新朋友。"}]},{unitId:"g5au2",title:"A Busy Week",titleCn:"忙碌的一周",warmup:"What do you usually do on weekdays?",warmupCn:"你工作日通常做什么？",en:"My week is busy. On weekdays, I always get up at six thirty. I usually have English class in the morning. I often play basketball after school. Sometimes I help my mum cook dinner. I never go to bed late. At the weekend, I visit my grandparents. I love my busy but happy week.",cn:"我的一周很忙。工作日我总是六点半起床，上午通常有英语课，放学后经常打篮球，有时帮妈妈做晚饭，从不晚睡。周末我去看望祖父母。我喜欢这忙碌又快乐的一周。",quiz:[{q:"When does the writer get up on weekdays?",options:["At six thirty","At seven","At eight"],answer:0,explain:"工作日六点半起床。"},{q:"What does the writer often do after school?",options:["Play basketball","Go swimming","Read books"],answer:0,explain:"放学后经常打篮球。"},{q:"What does the writer do at the weekend?",options:["Visit grandparents","Go to school","Play football"],answer:0,explain:"周末去看望祖父母。"}]},{unitId:"g5au3",title:"My Big Family",titleCn:"我的大家庭",warmup:"How many people are there in your family?",warmupCn:"你家有多少人？",en:"I have a big family. My grandparents live with us. My uncle and aunt often visit at the weekend. My cousin and I play together. My parents are busy, but we always have dinner together. We care about each other. I am proud of my family.",cn:"我有一个大家庭。祖父母和我们住在一起，叔叔阿姨经常周末来做客，表妹和我一起玩。父母很忙，但我们总是一起吃晚饭。我们互相关心，我为我的家庭感到自豪。",quiz:[{q:"Who lives with the writer?",options:["Grandparents","Uncle and aunt","Cousin"],answer:0,explain:"祖父母和作者住在一起。"},{q:"When do the uncle and aunt often visit?",options:["At the weekend","On Monday","Every morning"],answer:0,explain:"叔叔阿姨经常周末来。"},{q:"What does the family always do together?",options:["Have dinner","Play football","Go shopping"],answer:0,explain:"家人总是一起吃晚饭。"}]},{unitId:"g5au4",title:"A Picnic Plan",titleCn:"野餐计划",warmup:"What do you need for a picnic?",warmupCn:"野餐需要准备什么？",en:"Spring is coming. It is warm and sunny. My family is planning a picnic. We will go outdoors on Sunday. Mum prepares sandwiches and fruit. Dad takes a kite. I take my camera. We will watch the sunset together. I hope there is a rainbow in the sky.",cn:"春天来了，天气温暖晴朗。我们一家计划星期天去户外野餐。妈妈准备三明治和水果，爸爸带风筝，我带相机。我们将一起看日落。我希望天上会出现彩虹。",quiz:[{q:"When will they have the picnic?",options:["On Sunday","On Saturday","On Monday"],answer:0,explain:"他们星期天去野餐。"},{q:"What does Dad take?",options:["A kite","A camera","Sandwiches"],answer:0,explain:"爸爸带风筝。"},{q:"What does the writer hope to see?",options:["A rainbow","Snow","A boat"],answer:0,explain:"作者希望看到彩虹。"}]},{unitId:"g5au5",title:"A Trip to Guangzhou",titleCn:"广州之旅",warmup:"Where do you want to travel?",warmupCn:"你想去哪里旅行？",en:"Next week, my family is going to travel to Guangzhou. We will go by train. We are going to visit the museum and the beautiful Pearl River. We will stay in a small hotel near the metro. I will pack my suitcase and take my camera. I can't wait for the trip!",cn:"下周我们一家打算去广州旅行，坐火车去。我们打算参观博物馆和美丽的珠江，住在地铁附近的小酒店。我会收拾好行李箱，带上相机。我迫不及待想出发了！",quiz:[{q:"How will they go to Guangzhou?",options:["By train","By plane","By bus"],answer:0,explain:"他们坐火车去。"},{q:"Where will they stay?",options:["In a small hotel near the metro","At a friend's home","On the beach"],answer:0,explain:"住在地铁附近的小酒店。"},{q:"What will the writer take?",options:["A camera","A bike","A cat"],answer:0,explain:"作者会带相机。"}]},{unitId:"g5au6",title:"Healthy Habits",titleCn:"健康习惯",warmup:"What are your healthy habits?",warmupCn:"你有哪些健康习惯？",en:"Healthy habits keep us strong. We should eat vegetables and fruit every day. We should exercise for an hour. We should sleep eight hours at night. We should wash our hands before meals. Good habits give us energy and make us happy.",cn:"健康习惯让我们保持强壮。我们应该每天吃蔬菜和水果，锻炼一小时，晚上睡八小时，饭前洗手。好习惯给我们精力，也让我们快乐。",quiz:[{q:"How long should we exercise?",options:["For an hour","For ten minutes","For five hours"],answer:0,explain:"短文说 exercise for an hour。"},{q:"How many hours should we sleep?",options:["Eight","Six","Ten"],answer:0,explain:"晚上应睡八小时。"},{q:"What should we do before meals?",options:["Wash our hands","Run","Watch TV"],answer:0,explain:"饭前要洗手。"}]},{unitId:"g5bu1",title:"Rules at School",titleCn:"学校规则",warmup:"What rules does your school have?",warmupCn:"你的学校有哪些规则？",en:"Our school has many rules. We must arrive on time. We should stand in line and wait for our turn. We must keep quiet in the library. We should be polite to teachers and friends. We must not run in the hallway. Rules keep us safe and happy.",cn:"我们学校有很多规则。我们必须按时到校，排队等候，在图书馆保持安静，对老师和朋友有礼貌，不在走廊奔跑。规则让我们安全又快乐。",quiz:[{q:"What must students do in the library?",options:["Keep quiet","Run fast","Eat food"],answer:0,explain:"在图书馆必须保持安静。"},{q:"Where must students NOT run?",options:["In the hallway","On the playground","In the gym"],answer:0,explain:"不能在走廊奔跑。"},{q:"What do rules do for us?",options:["Keep us safe and happy","Make us tired","Give us homework"],answer:0,explain:"规则让我们安全快乐。"}]},{unitId:"g5bu2",title:"The Nature Park",titleCn:"自然公园",warmup:"What can you hear and see in nature?",warmupCn:"在自然中你能听到、看到什么？",en:"The nature park is beautiful. There is a high mountain and a long river. A small bridge is over the river. The forest is green. Birds sing in the trees. The air is fresh. We should take our rubbish home and protect nature.",cn:"自然公园很美。那里有一座高山和一条长河，河上有一座小桥，森林郁郁葱葱，鸟儿在树上歌唱，空气很新鲜。我们应该把垃圾带回家，保护自然。",quiz:[{q:"What is over the river?",options:["A small bridge","A big house","A mountain"],answer:0,explain:"河上有一座小桥。"},{q:"Where do the birds sing?",options:["In the trees","In the river","On the bridge"],answer:0,explain:"鸟儿在树上唱歌。"},{q:"What should we do with our rubbish?",options:["Take it home","Throw it in the river","Leave it in the forest"],answer:0,explain:"应该把垃圾带回家。"}]},{unitId:"g5bu3",title:"Chinese Culture Day",titleCn:"中国文化日",warmup:"What Chinese culture do you know?",warmupCn:"你了解哪些中国文化？",en:"Today is Chinese Culture Day at school. Mia shows us paper cutting. It is a traditional Chinese art. Amy learns to make dumplings. Ben watches Beijing opera with his grandpa. We share our culture with friends from other countries. Everyone loves it.",cn:"今天是学校中国文化日。米娅给我们展示剪纸——一门中国传统艺术。艾米学包饺子，本和爷爷一起看京剧。我们和来自其他国家的朋友分享文化，大家都很喜欢。",quiz:[{q:"What does Mia show?",options:["Paper cutting","Beijing opera","Dumplings"],answer:0,explain:"米娅展示剪纸。"},{q:"What does Amy learn to make?",options:["Dumplings","Cakes","Noodles"],answer:0,explain:"艾米学包饺子。"},{q:"Who watches Beijing opera?",options:["Ben and his grandpa","Mia and Amy","The teachers"],answer:0,explain:"本和爷爷看京剧。"}]},{unitId:"g5bu4",title:"My Hero",titleCn:"我心中的英雄",warmup:"Who do you admire?",warmupCn:"你钦佩谁？",en:"My hero is my mother. She is a nurse. She works hard every day. When people are sick, she takes care of them. She is brave and kind. She always tells me to be strong. I admire her courage. She is a good example for me. I want to be like her.",cn:"我心中的英雄是我妈妈，她是一名护士。她每天努力工作，照顾生病的人。她勇敢又善良，总是告诉我要坚强。我钦佩她的勇气，她是我学习的榜样。我想成为像她一样的人。",quiz:[{q:"What does the mother do?",options:["She is a nurse","She is a teacher","She is a driver"],answer:0,explain:"妈妈是护士。"},{q:"What does the mother tell the writer?",options:["To be strong","To be quiet","To run fast"],answer:0,explain:"妈妈让作者要坚强。"},{q:"Why does the writer admire her?",options:["Because of her courage","Because of her car","Because of her cooking"],answer:0,explain:"作者钦佩她的勇气。"}]},{unitId:"g5bu5",title:"A Cleaner Earth",titleCn:"更干净的地球",warmup:"What can you do for the earth?",warmupCn:"你能为地球做什么？",en:"The earth is our home. We should keep it clean. We can recycle paper, bottles and cans. We should save water and turn off the lights. We can bring our own bags and use less plastic. We can plant trees in spring. Small actions make a big difference.",cn:"地球是我们的家园，我们应该保持它的清洁。我们可以回收纸张、瓶子和易拉罐，节约用水、随手关灯，自带购物袋、少用塑料，春天还可以种树。小小的行动能带来大大的改变。",quiz:[{q:"What can we recycle?",options:["Paper, bottles and cans","Food and water","Books and pens"],answer:0,explain:"可以回收纸张、瓶子和易拉罐。"},{q:"What should we do with the lights?",options:["Turn them off","Turn them on all day","Break them"],answer:0,explain:"应该随手关灯。"},{q:"When can we plant trees?",options:["In spring","In winter","At night"],answer:0,explain:"春天可以种树。"}]},{unitId:"g5bu6",title:"Goodbye, Primary School",titleCn:"再见，小学",warmup:"What will you remember about primary school?",warmupCn:"你会记得小学的什么？",en:"Six years pass quickly. I remember my first day at school. I remember my teachers and my friends. We studied, played and grew together. Now we are going to graduate. I want to thank everyone. I will never forget these happy memories. I hope we all follow our dreams.",cn:"六年过得真快。我记得上学的第一天，记得老师和朋友们。我们一起学习、玩耍、成长。现在我们即将毕业，我想感谢每一个人。我永远不会忘记这些快乐的回忆。希望我们都追随自己的梦想。",quiz:[{q:"How many years does the writer remember?",options:["Six","Three","Five"],answer:0,explain:"短文说 Six years pass quickly。"},{q:"What does the writer want to do?",options:["Thank everyone","Leave school early","Forget friends"],answer:0,explain:"作者想感谢每一个人。"},{q:"What does the writer hope?",options:["They follow their dreams","They stop studying","They move away"],answer:0,explain:"作者希望大家都追随梦想。"}]},{unitId:"g6au1",title:"Growing Up",titleCn:"成长",warmup:"What can you do by yourself now?",warmupCn:"你现在能自己做什么？",en:"Growing up is not only about getting taller. It is also about learning new things and becoming more independent. I can now plan my homework and tidy my room by myself. When I meet problems, I try to be confident and careful. My parents say I have made great progress. I am proud of myself, and I know that responsibility comes with growing up.",cn:"长大不只是变高，也包括学习新事物、变得更加独立。现在我可以自己安排作业、整理房间。遇到问题时，我努力保持自信和细心。爸爸妈妈说我进步很大。我为自己感到自豪，也知道成长意味着承担责任。",quiz:[{q:"What is growing up about besides getting taller?",options:["Learning new things and becoming independent","Eating more food","Sleeping longer"],answer:0,explain:"长大也包括学习新事物、变得更独立。"},{q:"What does the writer try to be when meeting problems?",options:["Confident and careful","Angry and loud","Quiet and afraid"],answer:0,explain:"作者遇到问题时努力保持自信和细心。"},{q:"Who says the writer has made great progress?",options:["Parents","Teachers","Friends"],answer:0,explain:"爸爸妈妈说作者进步很大。"}]},{unitId:"g6au2",title:"Welcome to Guangzhou",titleCn:"欢迎来到广州",warmup:"What do you like most about your city?",warmupCn:"你最喜欢自己城市的什么？",en:"Guangzhou is a big city in the south of China. It has a long history, but it is also very modern. The Canton Tower stands by the Pearl River. Many people take the metro to work and travel. Visitors love Guangzhou dim sum. During Spring Festival, families go to the flower market and buy beautiful flowers. I love my city because it is warm, busy and full of life.",cn:"广州是中国南方的一座大城市。它历史悠久，同时又非常现代。广州塔矗立在珠江边，很多人坐地铁上班和出行。游客很喜欢广州点心。春节期间，一家人会去花市买漂亮的花。我爱我的城市，因为它温暖、热闹、充满活力。",quiz:[{q:"Where does the Canton Tower stand?",options:["By the Pearl River","On a mountain","In a park"],answer:0,explain:"广州塔矗立在珠江边。"},{q:"What do visitors love in Guangzhou?",options:["Dim sum","Pizza","Sushi"],answer:0,explain:"游客很喜欢广州点心。"},{q:"When do families go to the flower market?",options:["During Spring Festival","In summer","At Christmas"],answer:0,explain:"春节期间一家人会去花市。"}]},{unitId:"g6au3",title:"A Small World",titleCn:"小小的世界",warmup:"Which country would you like to visit?",warmupCn:"你想去哪个国家？",en:"The world is big, and every country is different. People speak different languages and have different cultures. On a map, we can find capitals, rivers and mountains. I have a pen friend in Canada. We write emails and share photos. I want to travel around the world one day and communicate with people from other countries.",cn:"世界很大，每个国家都不一样。人们说着不同的语言，有着不同的文化。在地图上，我们可以找到首都、河流和高山。我有一个加拿大的笔友，我们写邮件、分享照片。我希望有一天能环游世界，和不同国家的人交流。",quiz:[{q:"What can we find on a map?",options:["Capitals, rivers and mountains","Only animals","Only food"],answer:0,explain:"地图上能找到首都、河流和高山。"},{q:"Where is the writer's pen friend from?",options:["Canada","Australia","China"],answer:0,explain:"作者的笔友来自加拿大。"},{q:"What does the writer want to do one day?",options:["Travel around the world","Buy a map","Learn only one language"],answer:0,explain:"作者希望有一天环游世界。"}]},{unitId:"g6au4",title:"Technology Around Us",titleCn:"身边的科技",warmup:"What do you use a computer for?",warmupCn:"你用电脑做什么？",en:"Technology is all around us. We use the internet to find information and talk to friends. Robots can help people do difficult or dangerous work. We can learn online and write simple code. Technology makes our life easier and more interesting. However, we should use it well. Too much screen time is bad for our eyes, so we need to rest and exercise every day.",cn:"科技就在我们身边。我们用互联网查找信息、和朋友交流。机器人能帮人们做困难或危险的工作。我们可以在线学习，编写简单的代码。科技让生活更方便、更有趣。不过，我们要合理使用。看屏幕太久对眼睛不好，所以每天都要休息和运动。",quiz:[{q:"What can robots help people do?",options:["Difficult or dangerous work","Only sing songs","Only eat food"],answer:0,explain:"机器人能帮人们做困难或危险的工作。"},{q:"What is bad for our eyes?",options:["Too much screen time","Reading books","Playing outside"],answer:0,explain:"看屏幕太久对眼睛不好。"},{q:"What does technology make our life do?",options:["Easier and more interesting","Harder and slower","Quiet and boring"],answer:0,explain:"科技让生活更方便、更有趣。"}]},{unitId:"g6au5",title:"Small Actions, Big Changes",titleCn:"小行动，大改变",warmup:"What small things can you do for the earth?",warmupCn:"你能为地球做哪些小事？",en:"The earth is our home, but it is in danger. Pollution and waste are bad for the environment. We can do small things every day to help. We should recycle paper, glass and plastic. We should save water and energy at home. We can walk or take the metro instead of asking parents to drive. If everyone does a little, our planet will be cleaner and greener.",cn:"地球是我们的家，但它正处在危险中。污染和废弃物对环境有害。我们每天都能做些小事来帮忙。我们应该回收纸、玻璃和塑料，在家节约水和能源。我们可以走路或坐地铁，而不是让父母开车。如果每个人都做一点点，我们的星球会更干净、更绿。",quiz:[{q:"What are bad for the environment?",options:["Pollution and waste","Trees and flowers","Water and air"],answer:0,explain:"污染和废弃物对环境有害。"},{q:"What should we recycle?",options:["Paper, glass and plastic","Only food","Only water"],answer:0,explain:"我们应该回收纸、玻璃和塑料。"},{q:"What happens if everyone does a little?",options:["Our planet will be cleaner and greener","Nothing will change","The earth will get hotter"],answer:0,explain:"每个人都做一点，星球会更干净、更绿。"}]},{unitId:"g6au6",title:"Festivals in China",titleCn:"中国的节日",warmup:"What do you do with your family at festivals?",warmupCn:"过节时你和家人做什么？",en:"Festivals are an important part of our culture. During the Spring Festival, families gather and celebrate the new year. People put up red lanterns and wish each other good luck. At the Mid-Autumn Festival, we eat mooncakes and enjoy the full moon. In summer, dragon boat races are exciting to watch. These traditions bring people together, and every festival is full of joy.",cn:"节日是我们文化中重要的一部分。春节期间，家人团聚，庆祝新年。人们挂起红灯笼，互祝好运。中秋节，我们吃月饼、赏满月。夏天，龙舟比赛十分精彩。这些传统让人们聚在一起，每个节日都充满欢乐。",quiz:[{q:"What do people put up during Spring Festival?",options:["Red lanterns","Christmas trees","Kites"],answer:0,explain:"春节期间人们挂红灯笼。"},{q:"What do people eat at Mid-Autumn Festival?",options:["Mooncakes","Dumplings","Noodles"],answer:0,explain:"中秋节人们吃月饼。"},{q:"What are exciting to watch in summer?",options:["Dragon boat races","Flower markets","Snowball fights"],answer:0,explain:"夏天龙舟比赛很精彩。"}]},{unitId:"g6bu1",title:"A Busy but Happy Term",titleCn:"忙碌又快乐的一学期",warmup:"What is your favourite school activity?",warmupCn:"你最喜欢的校园活动是什么？",en:"The new term is busy but happy. We have many subjects, and every day is full. In the morning, we have four lessons. After school, I go to the art club. There is an activity every Wednesday. We also have exams, so I must finish my homework and practise carefully. I am tired sometimes, but I enjoy my school life because I learn new things and meet my friends.",cn:"新学期忙碌又快乐。我们有很多科目，每天都很充实。上午有四节课，放学后我去美术社团，每周三都有活动。我们还有考试，所以我必须完成作业、认真练习。有时我会累，但我喜欢我的校园生活，因为我能学到新东西，还能见到朋友。",quiz:[{q:"How many lessons does the writer have in the morning?",options:["Four","Three","Five"],answer:0,explain:"上午有四节课。"},{q:"When is the art club activity?",options:["Every Wednesday","Every Monday","Every Friday"],answer:0,explain:"美术社团每周三有活动。"},{q:"Why does the writer enjoy school life?",options:["Because of learning new things and meeting friends","Because of long holidays","Because of no homework"],answer:0,explain:"作者喜欢校园生活是因为能学新东西、见朋友。"}]},{unitId:"g6bu2",title:"A Plan for My Summer",titleCn:"我的暑假计划",warmup:"What is your goal for this year?",warmupCn:"你今年的目标是什么？",en:"Summer holiday is coming. I have made a plan for it. My first goal is to read more English books. I am going to choose five easy stories and read one every week. My second goal is to exercise. I will run in the park every morning. Of course, I also need time to relax. A good plan is the first step to achieve my goals, and I will try my best.",cn:"暑假就要来了，我已经制定好了计划。第一个目标是多读英语书。我打算选五本简单的故事书，每周读一本。第二个目标是锻炼身体，我每天早晨去公园跑步。当然，我也需要时间放松。好的计划是实现目标的第一步，我会尽最大努力。",quiz:[{q:"How many English books is the writer going to read?",options:["Five","Ten","Three"],answer:0,explain:"作者打算读五本英语故事书。"},{q:"When will the writer run?",options:["Every morning","Every evening","Every weekend"],answer:0,explain:"作者每天早晨跑步。"},{q:"What is the first step to achieve goals?",options:["A good plan","More sleep","More food"],answer:0,explain:"好的计划是实现目标的第一步。"}]},{unitId:"g6bu3",title:"Amazing Animals",titleCn:"神奇的动物",warmup:"Which animal do you like best?",warmupCn:"你最喜欢哪种动物？",en:"Animals are amazing. Elephants are the largest animals on land, and giraffes are the tallest. Dolphins live in the sea and are very clever. Penguins live in cold places, and camels can live in hot, dry deserts. Every animal has its own habitat. Many wild animals are in danger, so we must protect them and their homes. We should not buy things made from wild animals.",cn:"动物们很神奇。大象是陆地上最大的动物，长颈鹿是最高的。海豚生活在海里，非常聪明。企鹅生活在寒冷的地方，骆驼能生活在炎热干燥的沙漠里。每种动物都有自己的栖息地。许多野生动物正处在危险中，所以我们必须保护它们和它们的家园。我们不应该购买野生动物制品。",quiz:[{q:"Which animal is the tallest?",options:["The giraffe","The elephant","The camel"],answer:0,explain:"长颈鹿是最高的动物。"},{q:"Where do penguins live?",options:["In cold places","In the desert","In the sea"],answer:0,explain:"企鹅生活在寒冷的地方。"},{q:"What must we protect?",options:["Wild animals and their homes","Only zoo animals","Only pets"],answer:0,explain:"我们必须保护野生动物和它们的家园。"}]},{unitId:"g6bu4",title:"The Story of Nian",titleCn:"年的传说",warmup:"Do you know any Chinese legends?",warmupCn:"你知道哪些中国传说？",en:"Long ago, people were afraid of a monster called Nian. It came to the village at the end of every year. A brave boy had an idea. He asked people to put up red paper and make loud noises. When Nian saw the red colour and heard the noise, it ran away. Today, these traditions are still part of the Spring Festival. The story tells us that courage and wisdom can solve big problems.",cn:"很久以前，人们害怕一只叫“年”的怪兽。它每年年底都会来到村子。一个勇敢的男孩想出了一个办法。他让大家贴上红纸、弄出响亮的声响。当年看到红色、听到响声，就逃走了。今天，这些传统仍然是春节的一部分。这个故事告诉我们，勇气和智慧能解决大问题。",quiz:[{q:"What was Nian?",options:["A monster","A boy","A village"],answer:0,explain:"年是一只怪兽。"},{q:"What made Nian run away?",options:["Red colour and loud noise","Food and water","Songs and dances"],answer:0,explain:"红色和响声把年吓跑了。"},{q:"What does the story tell us?",options:["Courage and wisdom can solve big problems","Monsters are friendly","Red is a bad colour"],answer:0,explain:"故事告诉我们要有勇气和智慧。"}]},{unitId:"g6bu5",title:"A Healthy Life",titleCn:"健康生活",warmup:"What do you do to stay healthy?",warmupCn:"你怎样保持健康？",en:"Health is the most important thing in our life. To stay healthy, we need a good diet, enough exercise and sleep. We should eat more vegetables and fruit, and drink enough water. Exercise gives us energy and helps us relax. Too much stress is bad for us, so we need to find a balance between study and rest. A healthy life starts with small choices every day.",cn:"健康是我们生活中最重要的事。为了保持健康，我们需要良好的饮食、足够的锻炼和睡眠。应该多吃蔬菜水果，喝足够的水。锻炼给我们精力，也帮我们放松。压力太大会伤害我们，所以要找到学习和休息的平衡。健康生活从每天的小选择开始。",quiz:[{q:"What should we eat more?",options:["Vegetables and fruit","Sweets and cakes","Only meat"],answer:0,explain:"应该多吃蔬菜水果。"},{q:"What does exercise give us?",options:["Energy and helps us relax","More homework","Less sleep"],answer:0,explain:"锻炼给我们精力，也帮我们放松。"},{q:"What do we need between study and rest?",options:["A balance","More stress","More screen time"],answer:0,explain:"需要在学习和休息之间取得平衡。"}]},{unitId:"g6bu6",title:"Follow Your Dream",titleCn:"追随你的梦想",warmup:"What is your dream for the future?",warmupCn:"你未来的梦想是什么？",en:"Everyone has a dream. Some students want to be scientists, engineers or artists. I want to be an astronaut. I know it is not easy. I need to study hard, exercise every day and believe in myself. My teacher says that every big dream starts with a small step. I will keep trying, and I believe my dream will come true in the future.",cn:"每个人都有一个梦想。有的同学想成为科学家、工程师或艺术家。我想成为一名宇航员。我知道这并不容易。我需要努力学习、每天锻炼，并且相信自己。老师说，每一个远大的梦想都从一小步开始。我会不断努力，我相信未来我的梦想会实现。",quiz:[{q:"What does the writer want to be?",options:["An astronaut","An artist","An engineer"],answer:0,explain:"作者想成为一名宇航员。"},{q:"What does the writer need to do?",options:["Study hard, exercise and believe in himself","Only sleep more","Only watch TV"],answer:0,explain:"作者需要努力学习、锻炼并相信自己。"},{q:"What does every big dream start with?",options:["A small step","A lot of money","Good luck"],answer:0,explain:"每个大梦想都从一小步开始。"}]}],y={version:d,readings:p},m=c.lessons,w=y.readings,g=new Map(m.map(e=>[e.unitId,e])),i=new Map(w.map(e=>[e.unitId,e]));new Map(r.map(e=>[e.id,e]));function v(e){return g.get(e)}function f(e){return i.get(e)}function I(e){const n=s.find(a=>a.id===e);return n?n.units.map(a=>i.get(a.id)).filter(a=>!!a):[]}function W(e,n){return`${e}-d${n+1}`}function C(e){return`${e}-read`}function b(e){return e.en.trim().split(/\s+/).filter(Boolean).length}function M(e){return Math.max(1,Math.round(b(e)/70))}function T(e){const n=h(e);if(!n)return;const a=s.find(o=>o.id===n.bookId);if(!a)return;const t=a.units.find(o=>o.no===n.no+1);return t?i.get(t.id):void 0}export{b as a,M as b,f as c,W as d,C as e,v as g,T as n,I as r};
